const { regClass } = Laya;
import { NodeListItemBase } from "./NodeListItem.generated";
import { NodeItem } from "../../data/sheetItem/match/NodeItem";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import SheetDataManager from "../../global/SheetDataManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";

@regClass('PayHrcvHRHadv1wSa6XTzA==')
export class NodeListItem extends NodeListItemBase {
    public nodeItem: NodeItem;

    public constructor() {
        super();
    }
    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.changeNode);
        Signal.on(GameEvent.EVENT_Game_Delay, this, this.onUpdateNodeDelay);
    }

    public set dataSource(value: NodeItem) {
        super.dataSource = value;
        if (!value) {
            return;
        }

        this.nodeItem = value;
        this.tf_country.text = GameLanguageMgr.getLanguage(value.name);
        // let countryItem = SheetDataManager.m_dicCountry.get(value.area);

        this.img_flag.skin = GameResourceManager.getCountryIconById(value.area);

        // 显示上一次测量的延迟数据
        if (value.dT !== -1) {
            this.setDelay(value.dT);
        } else {
            this.tf_delay.text = "";
        }
    }

    private changeNode() {
        GlobalDataManager.nodeItem = this.nodeItem;
        // GlobalDataManager.currentNodeUrl = this.nodeItem.url;
        console.log("新节点", GlobalDataManager.nodeItem);

        // 同步节点的延迟值到首页的网络延迟显示组件
        // 使用getDisplayDelay方法获取更可靠的延迟显示值
        // if (this.nodeItem) {
        //     const displayDelay = this.nodeItem.getDisplayDelay();
        //     // 通过GameEvent.EVENT_Game_Delay事件将延迟值同步到NetDelaySign组件
        //     Signal.event(GameEvent.EVENT_Game_Delay, displayDelay);
        // }

        // 发送节点更改事件
        Signal.event(GameEvent.EVENT_CHANGE_NODE);
    }

    /**
     * 设置节点的延迟显示
     * @param delay 延迟时间（毫秒）
     */
    public setDelay(delay: number): void {
        if (!this.tf_delay) return;

        // // 将延迟值保存到节点项
        // if (this.nodeItem) {
        //     this.nodeItem.setDelay(delay);
        // }
var datas = SheetDataManager.getGeneralValueById(6);
        var d1 = datas ? datas[0] : 200; // 默认200
        var d2 = datas ? datas[1] : 500; // 默认500
        // 获取显示用的延迟值，可能是估计值
        const displayDelay = delay;

        // 根据延迟值设置不同颜色
        if (displayDelay === -1) {
            // 初始延迟值10000表示尚未测试，显示为待测试状态
            this.tf_delay.text = "-";
            this.tf_delay.color = "#FFFFFF"; // 白色
            // this.img_delay.skin = "res/common/comm/img_xh1.png";
        } else if (displayDelay >= 6000) {
            // 明确是超时状态，显示Timeout
            this.tf_delay.text = "6000ms";
            this.tf_delay.color = "#d93f3f"; // 红色
            // this.img_delay.skin = "res/common/comm/img_xh1.png";
            // console.log(`节点项 ${this.nodeItem?.id} 显示超时状态`);
        } else if (displayDelay > d2) {
            this.tf_delay.text = displayDelay + "ms";
            this.tf_delay.color = "#d93f3f"; // 红色
            // this.img_delay.skin = "res/common/comm/img_xh1.png";
        } else if (displayDelay > d1) {
            this.tf_delay.text = displayDelay + "ms";
            this.tf_delay.color = "#FFFF00"; // 黄色
            // this.img_delay.skin = "res/common/comm/img_xh2.png";
        } else {
            this.tf_delay.text = displayDelay + "ms";
            this.tf_delay.color = "#079a45"; // 绿色
            // this.img_delay.skin = "res/common/comm/img_xh3.png";
        }
    }
    onUpdateNodeDelay(nodeItem: NodeItem) {
        if (nodeItem === this.nodeItem) {
            this.setDelay(nodeItem.dT);
        }
    }

    onDisable(): void {
        this.nodeItem = null;
        Signal.off(GameEvent.EVENT_Game_Delay, this, this.onUpdateNodeDelay);
    }
}
