/**
 * 俱乐部管理类
 * 用于统一管理俱乐部数据
 */
class ClubManager {
    private static _instance: ClubManager;

    /** 俱乐部数据 */
    private m_clubData: any = null;
    
    /** 俱乐部房间数据 */
    private m_roomData: any[] = [];
    
    /** 俱乐部成员数据 */
    private m_memberData: any[] = [];
    
    /** 俱乐部社区数据 */
    private m_communityData: any[] = [];

    /** 我的佣金比例 */
    private m_profitRatio: number = 0;

    /**
     * 构造函数
     */
    private constructor() {
        // 私有构造函数，确保单例模式
    }

    /**
     * 获取单例实例
     */
    public static getInstance(): ClubManager {
        if (!ClubManager._instance) {
            ClubManager._instance = new ClubManager();
        }
        return ClubManager._instance;
    }

    /**
     * 设置俱乐部数据
     * @param clubData 俱乐部数据
     */
    public setClubData(clubData: any): void {
        if (!clubData) return;
        
        this.m_clubData = clubData;
        
        // 同时更新相关数据
        if (clubData.rooms) {
            this.m_roomData = clubData.rooms;
        }
        
        if (clubData.members) {
            this.m_memberData = clubData.members;
        }
        
        if (clubData.community) {
            this.m_communityData = clubData.community;
        }
    }

    /**
     * 获取俱乐部数据
     * @returns 俱乐部数据
     */
    public  getClubData(): any {
        return this.m_clubData;
    }

    /**
     * 获取俱乐部房间数据
     * @returns 俱乐部房间数据
     */
    public getRoomData(): any[] {
        return this.m_roomData;
    }

    /**
     * 设置俱乐部房间数据
     * @param roomData 房间数据
     */
    public setRoomData(roomData: any[]): void {
        if (!roomData) return;
        this.m_roomData = roomData;
    }

    /**
     * 获取俱乐部成员数据
     * @returns 俱乐部成员数据
     */
    public getMemberData(): any[] {
        return this.m_memberData;
    }

    /**
     * 设置俱乐部成员数据
     * @param memberData 成员数据
     */
    public setMemberData(memberData: any[]): void {
        if (!memberData) return;
        this.m_memberData = memberData;
    }

    /**
     * 获取俱乐部社区数据
     * @returns 俱乐部社区数据
     */
    public getCommunityData(): any[] {
        return this.m_communityData;
    }

    /**
     * 设置俱乐部社区数据
     * @param communityData 社区数据
     */
    public setCommunityData(communityData: any[]): void {
        if (!communityData) return;
        this.m_communityData = communityData;
    }

    /**
     * 设置我的佣金比例
     * @param profitRatio 佣金比例
     */
    public setProfitRatio(profitRatio: number): void {
        this.m_profitRatio = profitRatio;
    }

    /**
     * 获取我的佣金比例
     * @returns 佣金比例
     */
    public getProfitRatio(): number {
        return this.m_profitRatio;
    }

    /**
     * 清空俱乐部数据
     * 当关闭俱乐部页面时调用
     */
    public clearClubData(): void {
        this.m_clubData = null;
        this.m_roomData = [];
        this.m_memberData = [];
        this.m_communityData = [];
        this.m_profitRatio = 0;
    }

    /**
     * 更新俱乐部图标
     * @param iconValue 图标值
     */
    public updateClubIcon(iconValue: string): void {
        if (this.m_clubData) {
            this.m_clubData.icon = iconValue;
        }
    }

    /**
     * 更新俱乐部名称
     * @param nameValue 名称值
     */
    public updateClubName(nameValue: string): void {
        if (this.m_clubData) {
            this.m_clubData.name = nameValue;
        }
    }
}

export default ClubManager.getInstance(); 