import GameSetting from "../global/GameSetting";
import GlobalDataManager from "../global/GlobalDataManager";
import { com } from "../network/pb/socket";
import { Quick } from "./Quick";
import pako from "pako";
export class SocketDataUtil {
    /**
     * socketType 'HA'
     * @param messageType  pb中定义的消息编号，例如MSG_USER_LOGIN = 104
     * @param bodyArrayBuffer 消息体
     * @param magicStr 密钥
     */
    public static encodeMessage(messageType: any, bodyArrayBuffer: any, magicStr: any) {
        var messageHead = SocketDataUtil.createHeadMessage(messageType, magicStr);
        var messageBase = SocketDataUtil.createMessageBase(messageHead, bodyArrayBuffer);

        // //不使用压缩方式
        // var zlibMessageBuffer = messageBase.serializeBinary();

        //使用压缩方式
        var messageArrayBuffer = messageBase.serializeBinary();
        var zlibMessageBuffer = pako.gzip(messageArrayBuffer, { windowBits: 15, memLevel: 8 });

        var messageBodySize = zlibMessageBuffer.length;
        var messageHeadBuffer = new Uint8Array([
            (messageBodySize & 0xff000000) >>> 24,
            (messageBodySize & 0x00ff0000) >>> 16,
            (messageBodySize & 0x0000ff00) >>> 8,
            (messageBodySize & 0x000000ff) >>> 0
        ]);
        var message = new Uint8Array(messageHeadBuffer.byteLength + zlibMessageBuffer.byteLength);
        message.set(new Uint8Array(messageHeadBuffer), 0);
        message.set(new Uint8Array(zlibMessageBuffer), messageHeadBuffer.byteLength);
        return message;
    }
    public static encodeMessage1(messageType: any, bodyArrayBuffer: any, magicStr: any) {
        var messageHead = SocketDataUtil.createHeadMessage(messageType, magicStr);
        var messageBase = SocketDataUtil.createMessageBase(messageHead, bodyArrayBuffer);

        //不使用压缩方式
        var zlibMessageBuffer = messageBase.serializeBinary();

        // //使用压缩方式
        // var messageArrayBuffer = messageBase.serializeBinary();
        // var zlibMessageBuffer = pako.gzip(messageArrayBuffer, { windowBits: 15, memLevel: 8 });

        var messageBodySize = zlibMessageBuffer.length;
        var messageHeadBuffer = new Uint8Array([
            (messageBodySize & 0xff000000) >>> 24,
            (messageBodySize & 0x00ff0000) >>> 16,
            (messageBodySize & 0x0000ff00) >>> 8,
            (messageBodySize & 0x000000ff) >>> 0
        ]);
        var message = new Uint8Array(messageHeadBuffer.byteLength + zlibMessageBuffer.byteLength);
        message.set(new Uint8Array(messageHeadBuffer), 0);
        message.set(new Uint8Array(zlibMessageBuffer), messageHeadBuffer.byteLength);
        return message;
    }
    public static decodeMessage(arrayBuffer: Uint8Array): com.snake.socket.CMsgBase {
        // var buffer = new Uint8Array(arrayBuffer);
        // var pos = 0;
        // var messageBodySize = new DataView(arrayBuffer.buffer, pos + 0, pos + 4).getInt32(0, false);
        // var endPos: number = pos + 4 + messageBodySize;
        // var messageBodyArrayBuffer = arrayBuffer.slice(pos + 4, pos + 4 + messageBodySize);
        var messageBodyArrayBuffer = arrayBuffer;

        //使用压缩
        var inflator = new pako.Inflate();
        inflator.push(messageBodyArrayBuffer, true);
        if (inflator.err) {
            console.error(inflator.msg);
        }
        var unzipMessageBuffer: Uint8Array = inflator.result as Uint8Array;

        var messageBase = com.snake.socket.CMsgBase.deserializeBinary(unzipMessageBuffer);

        // //不使用压缩
        // var messageBase = com.snake.socket.CMsgBase.deserializeBinary(messageBodyArrayBuffer);

        return messageBase;
    }
    public static createHeadMessage(msgtype: any, magicStr: any, isrequesting?: boolean, roleId?: null) {
        if (!magicStr) {
            isrequesting = true;
        }
        if (!roleId && GlobalDataManager.playerDto) {
            roleId = GlobalDataManager.playerDto.pid;
        }

        var message = com.snake.socket.CMsgHead.fromObject({
            msgtype: msgtype,
            msgcode: 1,
            roleId: roleId
        });
        return message;
    }

    public static createMessageBase(msghead: com.snake.socket.CMsgHead, msgbody?: null) {
        var message = com.snake.socket.CMsgBase.fromObject({
            msghead: msghead,
            msgbody: msgbody
        });
        return message;
    }

    public static getMsgBody(messageBase: com.snake.socket.CMsgBase, className: any = null): any {
        var msgBody: any = null;
        var msgtype = messageBase.msghead.msgtype;
        var msgcode = messageBase.msghead.msgcode;
        if (!className) {
            className = Laya.ClassUtils.getClass(msgtype + "");
        }
        if (className) {
            msgBody = className.deserializeBinary(messageBase.msgbody).toObject();
            if (GameSetting.Debug == 2) {
                console.log(Quick.GetLogTime, "[DataUtil]  ------<<<<<<<< RECV CMD:" + msgtype + ", CODE:", msgcode + ", DATA:", msgBody);
            }
        } else {
            console.warn(Quick.GetLogTime, "[DataUtil]  ------<<<<<<<< RECV CMD:" + msgtype + ", CODE:", msgcode + ", className解析失败!");
        }
        return msgBody;
    }
}
