/**
 * 通用对象池管理器
 * @description 支持管理任意类型的对象池
 */
class ObjectPool {
    private static _instance: ObjectPool;
    private pools: Map<any, any[]> = new Map(); // 存储类型与对象池的映射
    private configs: Map<any, PoolConfig> = new Map(); // 类型配置信息

    private constructor() {}

    public static getInstance(): ObjectPool {
        if (!ObjectPool._instance) {
            ObjectPool._instance = new ObjectPool();
        }
        return ObjectPool._instance;
    }

    /**
     * 注册对象类型到对象池
     * @param type 对象构造函数
     * @param factory 对象创建工厂函数
     * @param initSize 初始预创建数量
     * @param maxSize 最大缓存数量（默认不限制）
     */
    register<T>(type: new (...args: any[]) => T, factory: () => T, initSize: number = 0, maxSize: number = Infinity): void {
        this.configs.set(type, { factory, maxSize });
        this.pools.set(type, []);

        // 预创建对象
        for (let i = 0; i < initSize; i++) {
            this.release(type, factory());
        }
    }

    /**
     * 从对象池获取对象
     * @param type 对象类型
     * @param args 初始化参数（需要对象实现init方法时使用）
     */
    get<T>(type: new (...args: any[]) => T, ...args: any[]): T {
        const pool = this.pools.get(type) as T[];
        if (!pool) throw new Error(`Type ${type.name} not registered`);

        const obj = pool.length > 0 ? pool.pop()! : this.configs.get(type)!.factory();

        // 如果对象有初始化方法
        if ((obj as any).init) {
            (obj as any).init(...args);
        }

        return obj;
    }

    /**
     * 释放对象回池
     * @param type 对象类型
     * @param obj 要释放的对象
     */
    release<T>(type: new (...args: any[]) => T, obj: T): void {
        const config = this.configs.get(type);
        if (!config) throw new Error(`Type ${type.name} not registered`);

        const pool = this.pools.get(type) as T[];

        // 执行清理方法
        if ((obj as any).reset) {
            (obj as any).reset();
        }

        if (pool.length < config.maxSize) {
            pool.push(obj);
        }
    }

    /**
     * 清空指定类型的对象池
     */
    clear<T>(type: new (...args: any[]) => T): void {
        this.pools.set(type, []);
    }

    /**
     * 清空所有对象池
     */
    clearAll(): void {
        this.pools.clear();
    }
}

interface PoolConfig {
    factory: () => any;
    maxSize: number;
}
export default ObjectPool.getInstance();
