    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;

    private m_currentTabIndex: number = 2; //当前选中的tab索引

    TAB_COUNT = 2;

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     * @param isFromAsset 是否是从资产界面点击进来的
     */
    private onTabClick(index: number): void {
        // 如果点击的是当前选中的tab且不是从资产界面点击进来的，直接返回
        if (this.m_currentTabIndex === index) {
            return;
        }
        this.m_currentTabIndex = index;

        // Tab相关常量定义

        const SKIN_SELECTED = "res/common/comm/img_com_tab1.png";
        const SKIN_UNSELECTED = "res/common/comm/img_com_tab2.png";
        const COLOR_SELECTED = "#93401a";
        const COLOR_UNSELECTED = "#ffeed3";
        // 遍历所有Tab按钮
        for (let i = 0; i < this.TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            // this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isSelected ? SKIN_SELECTED : SKIN_UNSELECTED;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.color = isSelected ? COLOR_SELECTED : COLOR_UNSELECTED;

            if (isSelected) {
                switch (index) {
                    case 0:
                        this.snakeList.visible = true;
                        this.propList.visible = false;

                        break;
                    case 1:
                        this.snakeList.visible = false;
                        this.propList.visible = true;
                        break;
                }
            }
        }
    }

    private type: number = 1;
    private selectItemId: number = -1;
    private shopId: number = 1; //选中的蛇的id

    setOpenData(datas: any): void {
        //根据参数切换优先显示的类目
        if (datas && datas.length > 0) {
            this.type = datas[0];
            if (datas[1] != undefined) {
                this.selectItemId = datas[1];
            }
            this.onTabClick(this.type);
        } else {
            //没有指定就显示默认第一个
            this.selectItemId = 1;
            this.onTabClick(this.selectItemId);
        }
        this.initBagInfo();
    }

    onEnable(): void {
        this.snakeList.visible = false;
        this.propList.visible = false;
        //注册事件左侧按钮点击（切换类型）
        for (let i = 0; i < this.TAB_COUNT; i++) {
            (this as any)["tab" + i].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }
        AnimationUtil.startJellyScaleAnimation(this.tf_tittle);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);

        Signal.on(GameEvent.EVENT_ITEM_UPDATE, this, this.onPackInfo);
        Signal.on(GameEvent.EVENT_SNAKE_UPDATE, this, this.onSnakePackInfo);
        Signal.on(GameEvent.UPDATE_BAG_INFO, this, this.initBagInfo);
    }

    public removeEvent(): void {}

