    // 显示结算界面
    public showScore(baseScore: number, combo: number): void {
        this.baseScore = baseScore;
        this.combo = combo;
        this.totalScore = baseScore; //this.calculateTotalScore();

        // 重置UI状态
        this.container.visible = true;
        this.container.scale(0.5, 0.5);
        this.container.alpha = 0;
        this.scoreLabel.text = "0";
        // this.comboLabel.text = "";

        // 隐藏星星
        for (let star of this.stars) {
            star.scale(0.1, 0.1);
            star.alpha = 0;
        }

        // 播放出现动画
        Laya.Tween.to(
            this.container,
            {
                scaleX: 1,
                scaleY: 1,
                alpha: 1
            },
            400,
            Laya.Ease.backOut,
            Laya.Handler.create(this, this.startScoreAnimation)
        );
    }

    // 计算总分
    private calculateTotalScore(): number {
        // 基础分 + 连击加成 (combo * 20%)
        return this.baseScore * (1 + this.combo * 0.2);
    }

    // 开始分数动画
    private startScoreAnimation(): void {
        this.isAnimating = true;

        // // 显示连击信息
        // this.comboLabel.text = `连击! x${this.combo}`;
        // this.comboLabel.scale(2, 2);
        // this.comboLabel.alpha = 0;

        // Laya.Tween.to(this.comboLabel, {
        //     scaleX: 1,
        //     scaleY: 1,
        //     alpha: 1
        // }, 300, Laya.Ease.backOut);

        // 分数滚动动画
        let currentScore = 0;
        const increment = this.totalScore / 30; // 分30步完成

        const animate = () => {
            currentScore += increment;
            if (currentScore >= this.totalScore) {
                currentScore = this.totalScore;
                Laya.timer.clear(this, animate);
                this.showStars();
            }
            this.scoreLabel.text = Math.floor(currentScore).toString();
        };

        Laya.timer.loop(20, this, animate);
    }
    private hasShowStars = false;

    // 显示星级评价
    private showStars(): void {
        if (this.hasShowStars) {
            return;
        }
        this.hasShowStars = true;
        const starCount = NumberUtil.calculateStarCount(this.totalScore);

        // 依次显示星星
        for (let i = 0; i < starCount; i++) {
            Laya.timer.once(300 * i, this, () => {
                const star = this.stars[i];
                star.alpha = 1;

                // 星星弹出效果
                const originalScale = 1;
                Laya.Tween.to(
                    star,
                    { scaleX: 1.2, scaleY: 1.2 },
                    150,
                    Laya.Ease.backOut,
                    Laya.Handler.create(this, () => {
                        Laya.Tween.to(star, { scaleX: originalScale, scaleY: originalScale }, 150, Laya.Ease.backOut);
                    })
                );

                // 粒子效果
                this.createStarParticles(star.x + star.width / 2, star.y + star.height / 2);
            });
        }

        // 动画完成后启用按钮
        Laya.timer.once(300 * starCount + 500, this, () => {
            this.isAnimating = false;
        });
    }

