const { regClass } = Laya;
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import { EnumConsumeType } from "../../data/enumData/EnumConsumeType";
import { NumberUtil } from "../../utils/NumberUtil";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import { KnapsackItemBase } from "./KnapsackItem.generated";

@regClass('LzxJYKybT/m3CJav3RyDmg==')
export class KnapsackItem extends KnapsackItemBase {
    public itemVo: ItemVo;
    public showAdd: boolean = false;
    private isAddEvent: boolean = false;

    public constructor() {
        super();
    }

    private addEvent() {
        if (!this.isAddEvent) {
            this.isAddEvent = true;
        }
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.itemVo = value as ItemVo;
        if (!this.itemVo) {
            return;
        }
        this.addEvent();
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        if (!this.itemVo) return;
        if (this.itemVo.id == EnumConsumeType.TYPE_QUAN_MNT) {
            //逆袭券特殊处理
            this.tf_quanId.visible = true;
            this.tf_quanId.text = this.itemVo.m_iPk;
        } else {
            this.tf_quanId.visible = false;
        }
        let itemItem = this.itemVo.itemItem;
        if (ModuleManager.intance.hasOpenView(ModuleName.PveChoosePropsDialog)) {
            this.txt_num.visible = false;
        }
        if (this.itemVo) {
            if (this.showAdd) {
                this.txt_num.text = "" + NumberUtil.formatNumber(this.itemVo.newAddCnt, 8); //有小数保留2位
            } else {
                if (this.itemVo.num) {
                    this.txt_num.text = "" + NumberUtil.formatNumber(this.itemVo.num, 8); //有小数保留2位
                } else {
                    this.txt_num.text = "" + NumberUtil.formatNumber(this.itemVo.newAddCnt, 8); //有小数保留2位
                }
            }

            this.img_icon.skin = this.itemVo.iconURL;
            this.img_box.skin = "gameIcon/items/itemBg/img_" + this.itemVo.quality + ".png";
        } else {
            this.txt_num.text = "";
            this.img_icon.skin = null; //"https://cdn.bunnyswap.cc/images/items/"+itemsStItem.icon;
            this.img_box.skin = "gameIcon/items/itemBg/img_0.png";
        }
        this.tf_isSch.visible = this.itemVo.isScholarship;
    }
}
