const { regClass, property } = Laya;
@regClass('Uq3IEB9CSNSU6R4gjfo1lw==')
export default class NumberIncrement extends Laya.Script {
    // 文本组件引用
    owner: Laya.FontClip;
    // 当前数值
    private currentValue: number = 0;
    // 目标数值
    private targetValue: number = 100;
    // 动画持续时间（秒）
    private duration: number = 2;
    // 模式 1=整数模式 2=小数模式 3=时间
    private dataMode: number = 1;

    onAwake(): void {
        // 获取同一节点上的Label组件
    }

    /**
     * 启动数字自增动画
     * @param targetValue 目标数值
     * @param duration 持续时间（秒）
     * @param dataMode 使用模式
     */
    public startIncrement(targetValue: number, duration: number = 2, dataMode: number = 1): void {
        this.targetValue = targetValue;
        this.duration = duration;
        this.dataMode = dataMode;
        this.currentValue = 0;

        // 立即更新初始值
        this.updateText();

        // 创建Tween动画
        Laya.Tween.to(
            this,
            {
                currentValue: this.targetValue,
                update: new Laya.Handler(this, this.updateText) // 关键修改：添加update回调
            },
            this.duration * 1000,
            Laya.Ease.linearIn,
            null, // 完成回调（不需要时可置空）
            null,
            true
        );
    }

    private updateText(): void {
        if (this.dataMode == 1) {
            this.owner.value = Math.round(this.currentValue).toString();
        } else if (this.dataMode == 3) {
            this.owner.value = TimeUtil.format(this.currentValue, ":", false);
        } else {
            this.owner.value = this.currentValue.toFixed(2);
        }
    }

    onDestroy(): void {
        // 组件销毁时停止动画
        Laya.Tween.killAll(this);
    }
}
