import GameResourceManager from "../../common/GameResourceManager";
import { LayerManager } from "../../common/LayerManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { PlayerUpgradeSuccessDialogBase } from "./PlayerUpgradeSuccessDialog.generated";
const { regClass } = Laya;

@regClass('gNPNtfC8SYW/NR7gSnpNlg==')
export class PlayerUpgradeSuccessDialog extends PlayerUpgradeSuccessDialogBase {
    public m_iLayerType: number = LayerManager.M_TOP;
    public m_iPositionType: number = LayerManager.CENTER;
    public constructor() {
        super();
    }

    onEnable(): void {
        // this.backLayer.alpha = 0;
        // this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 1 }, 200, Laya.Ease.linearIn);
        AnimationUtil.startElasticPopupAnimation(this.allBox, 150, 1.1, 100, 0.95, 80);
        this.btn_ok.on(Laya.Event.CLICK, this, this.close);
        // // 给this.img_this加一个一直旋转的动画，onDisable的时候销毁掉
        // this.initProp();
    }

    /**
     * 显示购买页信息
     * @param data
     */
    public setOpenData(data: com.snake.socket.SC_LVUP_NOTICE) {
        if (data) {
            console.log("收到升级通知:", data);
            let item = data.items[0];
            let itemId = item.itemId;
            let itemNum = item.num;
            const itemItem: ItemItem = SheetDataManager.m_dicItems.get(itemId);
            this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
            this.tf_num.text = `+${itemNum}`;
        }
    }

    onDisable(): void {
        // Laya.Tween.killAll(this.img_guang);
    }

    // private initProp() {
    //     Laya.Tween.to(
    //         this.img_guang,
    //         { rotation: 360 },
    //         2000,
    //         Laya.Ease.linearIn,
    //         Laya.Handler.create(this, () => {
    //             this.img_guang.rotation = 0;
    //             this.initProp();
    //         })
    //     );
    // }
}
