import SoundMgr from "../../common/SoundMgr";
import { StageCellItem } from "../../data/sheetItem/match/StageCellItem";
import SheetDataManager from "../../global/SheetDataManager";
import { ObstacleCellViewBase } from "./ObstacleCellView.generated";
const { regClass } = Laya;

@regClass('ek6YwBnoTt25E2Vappu/cw==')
export default class ObstacleCellView extends ObstacleCellViewBase {
    // private img: Laya.Image;
    obstacleModel: any;

    onEnable(): void {
        // 初始化图片节点
        // this.img = this.getChildByName("img") as Laya.Image;
    }

    /**
     * 初始化障碍物表现
     * @param obstacleModel
     */
    initWithModel(obstacleModel: StageCellItem): void {
        this.obstacleModel = obstacleModel;
        // 查表获取icon
        const obsCfg: StageCellItem = SheetDataManager.m_dicStageCells.get(obstacleModel.id);
        // const obsCfg = OBSTACLE_CONFIGS.find((cfg) => cfg.id === obstacleModel.type);
        if (obsCfg && obsCfg.icon) {
            this.img.skin = obsCfg.icon;
        }
        // 可扩展动画、特效等
    }

    /**
     * 设置选中状态（可选：障碍物高亮、闪烁等特效）
     */
    setSelect(flag: boolean): void {
        if (flag) {
            // 选中特效（如高亮、闪烁等）
            this.img.alpha = 0.7;
        } else {
            // 恢复普通状态
            this.img.alpha = 1;
        }
    }

    /**
     * 消除时缩小+变透明动画
     */
    playDieEffect(): void {
        SoundMgr.playSoundByName(SoundMgr.soundName_iceblock_break);
        Laya.Tween.to(
            this,
            { scaleX: 0.2, scaleY: 0.2, alpha: 0 },
            200,
            Laya.Ease.quadIn,
            Laya.Handler.create(this, () => {
                this.removeSelf();
            })
        );
    }
}
