    /**
     * 批量推送消息
     * @param msgPushBody
     */
    pushMsg(msgPushBody: com.snake.socket.SC_PUSH) {
        var serverFrame = msgPushBody.frame;
        var msgList = msgPushBody.msgList;
        var oprBodys: ServerCmdDataDto[] = [];
        var eventFrame = 1000000000000;
        msgList.forEach((msgBase) => {
            var msgtype = msgBase.msghead.msgtype;
            var msgcode = msgBase.msghead.msgcode;
            var msgBody;

            var className = Laya.ClassUtils.getClass(msgtype + "");
            if (className) {
                var t1 = Date.now();
                msgBody = className.deserializeBinary(msgBase.msgbody).toObject();

                if (GameSetting.Debug >= 1) {
                    var t2 = Date.now();
                    console.log(
                        Quick.GetLogTime + " " + "WS ------<<<<<<<< RECV BATCH_CMD:" + msgtype + ", CODE:",
                        msgcode + ", DATA:",
                        msgBody,
                        " dt:",
                        t2 - t1
                    );
                }
            } else {
                if (GameSetting.Debug >= 1)
                    console.warn(
                        Quick.GetLogTime + " " + "WS ------<<<<<<<< RECV BATCH_CMD:" + msgtype + ", CODE:",
                        msgcode + ", className解析失败!"
                    );
            }
            if (msgtype == com.snake.socket.MessageType.MSG_PLAYER_COLLISION) {
                //返回碰撞不加入帧序列数据，只作为确认数据
                this.confirmPlayerCollision(msgBody, true);
            } else {
                var serverCmdDataDto: ServerCmdDataDto = new ServerCmdDataDto();
                serverCmdDataDto.msgtype = msgtype;
                serverCmdDataDto.msgBody = msgBody;
                var _eventFrame = msgBody.frame;
                if (_eventFrame < eventFrame) {
                    eventFrame = _eventFrame;
                }
                oprBodys.push(serverCmdDataDto);
            }
        });

        if (oprBodys && oprBodys.length) {
            // var serverFrameDataDto: ServerFrameDataDto = new ServerFrameDataDto();
            // serverFrameDataDto.frame = serverFrame;
            // serverFrameDataDto.minEventFrame = eventFrame;
            // serverFrameDataDto.serverCmdDataDtos = oprBodys;

            // var oprData = {frame:serverFrame, operations:[msgtype, oprBodys]};//暂时模拟一条，后续需要服务器合并帧推送；
            // ======提示====   2-1、客户端将操作集合加入到帧同步列表
            this.addFrameOperations(oprBodys);
        }
    }

