    handleOperationDetail(data: ServerCmdDataDto, isLogicSnake: boolean, hasConfirmed: boolean): void {
        if (GameSetting.Debug > 2) console.log("======handleOperationDetail=====", data.msgBody.frame, data, "isLogicSnake: " + isLogicSnake);
        switch (data.msgtype) {
            case com.snake.socket.MessageType.MSG_PLAYER_OPR:
                var msgOprBody = data.msgBody as com.snake.socket.CS_PLAYER_OPR;
                this.onRevOprPush(msgOprBody, isLogicSnake, hasConfirmed);
                break;
            case com.snake.socket.MessageType.MSG_EAT_FOOD: //吃食物
                let msgEatFoodBody = data.msgBody as SC_EAT_FOOD;
                // console.log("收到了 吃食物 数据返回", msgEatFoodBody);
                // this.eatFood(msgEatFoodBody, true);//暂时不用服务器吃食物
                break;
            case com.snake.socket.MessageType.MSG_PLAYER_COLLISION: //玩家碰撞
                let msgPlayerCollisionBody = data.msgBody as com.snake.socket.SC_PLAYER_COLLISION;
                // console.log("收到了 玩家碰撞 数据返回", msgPlayerCollisionBody);
                // this.playerCollision(msgPlayerCollisionBody, true);
                break;
            case com.snake.socket.MessageType.MSG_NOTICE_ENTER: //通知其他玩家进入
                // let msgNoticeBody = data.msgBody as com.snake.socket.SS_NOTICE_ENTER;
                // // console.log("收到了 通知其他玩家进入 数据返回", msgNoticeBody);
                // var onePlayer = msgNoticeBody.players;
                var onePlayer = data.msgBody;
                SnakeManager.getInstance().newAddSnake(onePlayer);

                break;
        }
    }

    confirmPlayerCollision(msgPlayerCollisionBody: com.snake.socket.SC_PLAYER_COLLISION, isServer: boolean) {
        var roleId = msgPlayerCollisionBody.roleId; //玩家id
        var foods = msgPlayerCollisionBody.food; //食物信息
        var targetId = msgPlayerCollisionBody.taret; //目标玩家id
        var head = msgPlayerCollisionBody.head; //头信息
        var serverFrame = msgPlayerCollisionBody.frame;
        var die = msgPlayerCollisionBody.die; //死亡的roleid
        // MatchModel.serverFrame = serverFrame;
        var snake: Snake = SnakeManager.getInstance().getRoleById(roleId);
        if (snake) {
            // snake.setIsSend(false, true); //恢复后面蛇发送状态
            if (die == "-1") {
                // snake.reAlive();
            } else {
                var targetSnake: Snake = SnakeManager.getInstance().getRoleById(targetId);

                if (die == roleId) {
                    snake.confirmDie();
                    if (targetSnake) targetSnake.addKill(1);

                    // GameManager.removeRoleById(roleId);
                } else {
                    if (targetSnake) targetSnake.confirmDie();
                    snake.addKill(1);
                }

                // if(!snake.isAlive()){
                // snake.die();
                // }

                if (foods && foods.length) {
                    FoodManager.addFoods(foods, true);
                }
            }
        }
    }

