    // 添加操作到指定帧
    public addOperation(operation: ServerCmdDataDto): void {
        var eventFrame = operation.msgBody.frame + 1;

        if (operation.msgBody.frame < FrameSyncManager.startFrame) {
            console.log(
                Quick.GetLogTime,
                "addOperation: 收到帧小于开始帧，直接丢弃",
                "frame: " + operation.msgBody.frame,
                "startFrame: " + FrameSyncManager.startFrame
            );
            //收到的帧小于开始帧，直接丢弃，合并106命令后，115命令后，有时会收到之前的帧数据
            return;
        }
        // var realFrame = operation.msgBody.frame + 1;
        if (GameSetting.Debug > 2) {
            console.log("addOperation (frame+1): ", eventFrame, operation);
        }

        if (!this._operationQueue[eventFrame]) {
            this._operationQueue[eventFrame] = [];
        }
        this._operationQueue[eventFrame].push(operation);

        // this.latestEventFrame 初始值 = 开局帧
        if (eventFrame > this.latestEventFrame) {
            this.latestEventFrame = eventFrame;
        }

        var tempFrame = 0;
        if (GameSetting.Debug > 2) {
            console.debug(
                "addOperation 收到帧 (frame+1): " +
                    eventFrame +
                    ", confirmedFrame: " +
                    FrameSyncManager.confirmedFrame +
                    ", rollBackConfirmedFrame: " +
                    FrameSyncManager.rollBackConfirmedFrame +
                    ", tempFrame: " +
                    tempFrame +
                    ", dFrame: " +
                    (eventFrame - FrameSyncManager.confirmedFrame)
            );
        }

        if (eventFrame <= FrameSyncManager.confirmedFrame) {
            // FrameSyncManager.rollBackConfirmedFrame = eventFrame;
            tempFrame = eventFrame;
        }
        if (tempFrame != 0 && tempFrame < FrameSyncManager.rollBackConfirmedFrame) {
            FrameSyncManager.rollBackConfirmedFrame = tempFrame;
        }
    }

