    onRevOprPush(opr: com.snake.socket.CS_PLAYER_OPR, isLogicSnake: boolean, hasConfirmed: boolean) {
        // console.log("onRevMovePush: ", roomPlayerMovePush );
        if (opr == null) {
            return;
        }

        var snake = SnakeManager.getInstance().getRoleById(opr.roleId);
        if (snake) {
            if (isLogicSnake) snake.logicSnake.updateHead106(opr.frame, opr.head, hasConfirmed, opr.oprIndex);
            //opr=  1转向2加速
            // console.log("applyOperation", roomPlayerMovePush);
            if (opr.opr == 1) {
                var direction = opr.value;
                snake.rotate(direction, isLogicSnake);
                // console.log("applyOperation rorate: ", direction);
            } else if (opr.opr == 2) {
                var rate = opr.value;
                snake.updateSpeedRate(rate, isLogicSnake);
                // console.log("applyOperation updateSpeedRate: ", rate);
            }
        } else {
            console.log(opr.roleId + " snake is null");
        }
    }
