// CellModel.ts

import { StageCellItem } from "../../data/sheetItem/match/StageCellItem";
import { CELL_STATUS, CELL_TYPE, ANITIME } from "./ConstValue";
import { IDGen } from "./IDGen";

/**
 * 模型基类
 */
class BaseModel {
  id: number; // 唯一ID

  constructor() {
    this.id = IDGen.genID();
  }
}

/**
 * 格子模型
 */
export default class CellModel extends BaseModel {
    type: number; // 格子类型
    status: string; // 当前状态
    swapFromStatus: string; // 交换的状态
    swapFromId: number; // 交换的ID
    swapFromX: number; // 交换的X
    swapFromY: number; // 交换的Y

    x: number; // 当前列坐标
    y: number; // 当前行坐标
    startX: number; // 初始列坐标
    startY: number; // 初始行坐标
    cmd: any[]; // 操作命令队列
    isDeath: boolean; // 是否已死亡
    objectCount: number; // 对象计数（用于随机）
    obstacle: StageCellItem; // 障碍物模型

    constructor() {
        super();
        this.type = null;
        this.status = CELL_STATUS.NORMAL;
        this.swapFromStatus = CELL_STATUS.NORMAL;
        this.swapFromId = 0;
        this.swapFromX = 0;
        this.swapFromY = 0;
        this.x = 1;
        this.y = 1;
        this.startX = 1;
        this.startY = 1;
        this.cmd = [];
        this.isDeath = false;
        this.objectCount = Math.floor(Math.random() * 1000);
        this.obstacle = null;
    }

    /**
     * 设置格子类型
     * @param type 格子类型
     */
    setType(type: number): void {
        this.type = type;
    }

    /**
     * 检查是否为空格子
     * @returns 是否为空
     */
    isEmpty(): boolean {
        return this.type == CELL_TYPE.EMPTY;
    }

    /**
     * 设置为空格子
     */
    setEmpty(): void {
        this.type = CELL_TYPE.EMPTY;
    }

    /**
     * 设置坐标
     * @param x 列坐标
     * @param y 行坐标
     */
    setXY(x: number, y: number): void {
        this.x = x;
        this.y = y;
    }

    /**
     * 设置初始坐标
     * @param x 列坐标
     * @param y 行坐标
     */
    setStartXY(x: number, y: number): void {
        this.startX = x;
        this.startY = y;
    }

    /**
     * 设置状态
     * @param status 新状态
     */
    setStatus(status: string): void {
        this.status = status;
    }

    /**
     * 移动到目标位置并返回
     * @param pos 目标位置
     */
    moveToAndBack(pos: Laya.Point): void {
        const srcPos = new Laya.Point(this.x, this.y);
        // 移动到目标位置
        this.cmd.push({
            action: "moveTo",
            keepTime: ANITIME.TOUCH_MOVE,
            playTime: 0,
            pos: pos
        });
        // 返回原位置
        this.cmd.push({
            action: "moveTo",
            keepTime: ANITIME.TOUCH_MOVE,
            playTime: ANITIME.TOUCH_MOVE,
            pos: srcPos
        });
    }

    /**
     * 移动到目标位置
     * @param pos 目标位置
     * @param playTime 播放时间
     */
    moveTo(pos: Laya.Point, playTime: number): void {
        this.cmd.push({
            action: "moveTo",
            keepTime: ANITIME.TOUCH_MOVE,
            playTime: playTime,
            pos: pos
        });
        this.x = pos.x;
        this.y = pos.y;
    }

    /**
     * 死亡操作
     * @param playTime 播放时间
     */
    toDie(playTime: number): void {
        this.cmd.push({
            action: "toDie",
            playTime: playTime,
            keepTime: ANITIME.DIE
        });
        this.isDeath = true;
    }

    /**
     * 抖动效果
     * @param playTime 播放时间
     */
    toShake(playTime: number): void {
        this.cmd.push({
            action: "toShake",
            playTime: playTime,
            keepTime: ANITIME.DIE_SHAKE
        });
    }

    /**
     * 设置可见性
     * @param playTime 播放时间
     * @param isVisible 是否可见
     */
    setVisible(playTime: number, isVisible: boolean): void {
        this.cmd.push({
            action: "setVisible",
            playTime: playTime,
            keepTime: 0,
            isVisible: isVisible
        });
    }

    /**
     * 移动到目标位置并死亡
     * @param pos 目标位置
     */
    moveToAndDie(pos: Laya.Point): void {
        // 具体实现
    }

    /**
     * 检查是否是鸟
     * @returns 是否是鸟
     */
    isBird(): boolean {
        return this.type == CELL_TYPE.BIRD;
    }

    /**
     * 检查是否存在障碍物
     * @returns 是否存在障碍物
     */
    hasObstacle(): boolean {
        return this.obstacle !== null;
    }

    /**
     * 检查是否可以被压碎
     * @returns 是否可以被压碎
     */
    canBeCrushed(): boolean {
        // 根据障碍物类型判断
        if (this.obstacle) {
            // 假设ObstacleModel有isCrushable属性
            return this.obstacle.canBeCleared == 1;
        }
        return false;
    }

    /**
     * 移除障碍物层，保留动物层
     * @returns 是否成功移除障碍物
     */
    removeObstacle(): boolean {
        if (this.obstacle && this.canBeCrushed()) {
            console.log(`[移除障碍物] 移除位置 id: ${this.id}, y: ${this.y}, x: ${this.x} , status: ${this.status} 的障碍物`);
            this.obstacle = null;
            return true;
        }
        return false;
    }

    /**
     * 检查是否有可消除的障碍物
     * @returns 是否有可消除的障碍物
     */
    hasCrushableObstacle(): boolean {
        return this.hasObstacle() && this.canBeCrushed();
    }
}
