const { regClass } = Laya;
import { loop } from "viem/chains";
import { BossBarBase } from "./BossBar.generated";
import SoundMgr from "../../common/SoundMgr";

@regClass('snmqvqdhSbK7PFnTwSLCYg==')
export class BossBar extends BossBarBase {
    private maxHp: number;
    private currentHp: number;

    /**
     * 初始化血条
     * @param parent 父容器
     * @param x X坐标
     * @param y Y坐标
     * @param width 宽度
     * @param height 高度
     */
    public init(parent: Laya.Sprite, x: number, y: number, width: number = 200, height: number = 20): void {
        // 初始化血量
        this.updateHealth(this.maxHp, this.maxHp);
    }

    /**
     * 更新血量
     * @param currentHp 当前血量
     * @param maxHp 最大血量
     */
    public updateHealth(currentHp: number, maxHp: number): void {
        this.currentHp = Math.max(0, currentHp);
        this.maxHp = maxHp;

        // 更新血条宽度
        const healthPercent = this.currentHp / this.maxHp;
        // const barWidth = this.healthBarBg.width * healthPercent;

        // // 清除旧的血条
        // this.healthBar.graphics.clear();

        // 根据血量百分比设置颜色
        let color = "#00FF00"; // 绿色
        if (healthPercent < 0.3) {
            color = "#FF0000"; // 红色
        } else if (healthPercent < 0.6) {
            color = "#FFFF00"; // 黄色
        }

        // this.healthBar.graphics.drawRect(0, 0, barWidth, this.healthBarBg.height, color);
        this.healthBar.value = healthPercent;

        // 更新血量文本
        this.healthText.text = `${this.currentHp}/${this.maxHp}`;
        this.healthText.color = color;

        // 血量变化动画
        this.playHealthChangeAnimation();
    }

    /**
     * 播放血量变化动画
     */
    private playHealthChangeAnimation(): void {
        // 血条闪烁效果
        const originalAlpha = this.healthBar.alpha;
        Laya.Tween.to(
            this.healthBar,
            { alpha: 0.5 },
            100,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(this.healthBar, { alpha: originalAlpha }, 100, Laya.Ease.backOut);
            })
        );

        // 血量文本缩放效果
        const originalScale = this.healthText.scaleX;
        Laya.Tween.to(
            this.healthText,
            { scaleX: 1.2, scaleY: 1.2 },
            150,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(this.healthText, { scaleX: originalScale, scaleY: originalScale }, 150, Laya.Ease.backOut);
            })
        );
    }

    /**
     * 播放受击效果
     */
    public playHitEffect(): void {
        // 整个血条容器抖动
        const originalX = this.healthBar.x;
        const originalY = this.healthBar.y;

        Laya.Tween.to(
            this.healthBar,
            { x: originalX + 3 },
            50,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(
                    this.healthBar,
                    { x: originalX - 3 },
                    50,
                    Laya.Ease.backOut,
                    Laya.Handler.create(this, () => {
                        Laya.Tween.to(this.healthBar, { x: originalX }, 50, Laya.Ease.backOut);
                    })
                );
            })
        );

        // // Boss图标闪烁
        // const originalAlpha = this.boss.alpha;
        // Laya.Tween.to(
        //     this.boss,
        //     { alpha: 0.3 },
        //     100,
        //     Laya.Ease.backOut,
        //     Laya.Handler.create(this, () => {
        //         Laya.Tween.to(this.boss, { alpha: originalAlpha }, 100, Laya.Ease.backOut);
        //     })
        // );
        if (this.hasResult == true) {
            return;
        }
        this.play("animation2", false);
        Laya.timer.once(1000, this, this.playIdle);
    }

    /**
     * 设置Boss图标
     * @param iconPath 图标路径
     */
    public play(aniName: string, loop: boolean): void {
        var spine2DRenderNode: Laya.Spine2DRenderNode = this.boss.getComponent(Laya.Spine2DRenderNode);
        spine2DRenderNode.play(aniName, loop);
    }
    /**
     * 设置Boss图标
     * @param iconPath 图标路径
     */
    public stop(): void {
        var spine2DRenderNode: Laya.Spine2DRenderNode = this.boss.getComponent(Laya.Spine2DRenderNode);
        spine2DRenderNode.stop();
    }
    hasResult = false;

    public playIdle() {
        this.play("animation1", true);
    }
    public playWin() {
        console.log("RESULT: playWin");
        this.hasResult = true;
        Laya.timer.clear(this, this.playIdle);
        this.play("animation3", true);
    }
    // public playLose() {
    //     console.log("RESULT: playLose");
    //     this.hasResult = true;
    //     Laya.timer.clear(this, this.playIdle);
    //     this.play("animation3", true);
    // }

    public playLose() {
        console.log("RESULT: playLose");
        this.hasResult = true;
        Laya.timer.clear(this, this.playIdle);

        // 开始Boss失败的多阶段动画效果
        this.playBossDefeatSequence();
    }

    /**
     * 播放Boss失败的完整动画序列
     */
    private playBossDefeatSequence(): void {
        // 第一阶段：Boss受到致命一击的反应
        this.playFinalHitEffect();

        // 第二阶段：Boss开始倒下动画
        Laya.timer.once(800, this, this.playCollapseEffect);

        // 第三阶段：Boss完全败北
        Laya.timer.once(2000, this, this.playFinalDefeatEffect);
    }

    /**
     * 第一阶段：致命一击效果
     */
    private playFinalHitEffect(): void {
        // 1. 屏幕震动效果（模拟重击感）
        this.playScreenShake();

        // 2. Boss剧烈抖动
        const originalX = this.boss.x;
        const originalY = this.boss.y;
        let shakeCount = 0;
        const maxShakes = 8;

        // 修复：使用命名函数而不是arguments.callee
        const bossShakeHandler = () => {
            if (shakeCount >= maxShakes) {
                Laya.timer.clear(this, bossShakeHandler);
                this.boss.x = originalX;
                this.boss.y = originalY;
                return;
            }

            const shakeIntensity = 8 - shakeCount; // 震动强度递减
            this.boss.x = originalX + (Math.random() - 0.5) * shakeIntensity;
            this.boss.y = originalY + (Math.random() - 0.5) * shakeIntensity;
            shakeCount++;
        };

        Laya.timer.loop(60, this, bossShakeHandler);

        // 3. 血条闪烁红色警告
        this.playHealthBarCriticalFlash();

        // 4. Boss表情变化（如果有受击动画）
        this.play("animation2", false); // 使用现有的animation2动画
    }

    /**
     * 屏幕震动效果
     */
    private playScreenShake(): void {
        const stage = Laya.stage;
        const originalX = stage.x;
        const originalY = stage.y;
        let shakeCount = 0;
        const maxShakes = 12;

        // 修复：使用命名函数而不是arguments.callee
        const screenShakeHandler = () => {
            if (shakeCount >= maxShakes) {
                Laya.timer.clear(this, screenShakeHandler);
                stage.x = originalX;
                stage.y = originalY;
                return;
            }

            const intensity = 6 * (1 - shakeCount / maxShakes); // 震动强度递减
            stage.x = originalX + (Math.random() - 0.5) * intensity;
            stage.y = originalY + (Math.random() - 0.5) * intensity;
            shakeCount++;
        };

        Laya.timer.loop(50, this, screenShakeHandler);
    }

    /**
     * 血条危险闪烁效果
     */
    private playHealthBarCriticalFlash(): void {
        let flashCount = 0;
        const maxFlashes = 6;

        // 修复：使用命名函数而不是arguments.callee
        const flashHandler = () => {
            if (flashCount >= maxFlashes) {
                Laya.timer.clear(this, flashHandler);
                this.healthBar.alpha = 1;
                this.healthBar.filters = null;
                return;
            }

            // 红色闪烁效果
            this.healthBar.alpha = flashCount % 2 === 0 ? 0.3 : 1;
            // 可以添加红色滤镜效果
            if (flashCount % 2 === 0) {
                this.healthBar.filters = [
                    new Laya.ColorFilter([
                        1,
                        0,
                        0,
                        0,
                        50, // 增加红色
                        0,
                        0.5,
                        0,
                        0,
                        0, // 减少绿色
                        0,
                        0,
                        0.5,
                        0,
                        0, // 减少蓝色
                        0,
                        0,
                        0,
                        1,
                        0 // 保持透明度
                    ])
                ];
            } else {
                this.healthBar.filters = null;
            }
            flashCount++;
        };

        Laya.timer.loop(150, this, flashHandler);
    }

    /**
     * 第二阶段：倒下效果
     */
    private playCollapseEffect(): void {
        // 1. Boss开始倒下动画
        this.play("animation2", false); // 使用现有的animation2动画
        
        // 2. Boss缓慢缩放和旋转（倒下效果）
        Laya.Tween.to(
            this.boss,
            {
                scaleX: 0.8,
                scaleY: 0.8,
                rotation: -15, // 轻微倾斜
                alpha: 0.7
            },
            1200,
            Laya.Ease.quadOut
        );

        // 3. 血条逐渐变暗
        Laya.Tween.to(
            this.healthBar,
            {
                alpha: 0.5
            },
            1000,
            Laya.Ease.sineOut
        );

        // 4. 血量文本变灰
        Laya.Tween.to(
            this.healthText,
            {
                alpha: 0.6
            },
            800,
            Laya.Ease.sineOut,
            Laya.Handler.create(this, () => {
                this.healthText.color = "#666666"; // 变为灰色
            })
        );
    }

    /**
     * 第三阶段：最终败北效果
     */
    private playFinalDefeatEffect(): void {
        SoundMgr.playSoundByName(SoundMgr.soundName_kill_die);
        // 1. Boss最终败北动画
        this.stop();
        // this.play("animation3", true); // 使用现有的animation3动画

        // 2. Boss完全倒下（更大的缩放和旋转）
        Laya.Tween.to(
            this.boss,
            {
                scaleX: 0.6,
                scaleY: 0.6,
                rotation: -45,
                alpha: 0.4,
                y: this.boss.y + 20 // 向下移动，模拟倒地
            },
            1500,
            Laya.Ease.backOut
        );

        // 3. 添加败北特效（如果需要）
        this.playDefeatParticles();

        // 4. 血条和文本最终状态
        Laya.Tween.to(
            this.healthBar,
            {
                alpha: 0.3
            },
            1000,
            Laya.Ease.sineOut
        );

        this.healthText.text = "DEFEATED";
        this.healthText.color = "#FF0000";

        // 5. 整体UI轻微下沉效果
        Laya.Tween.to(
            this,
            {
                y: this.y + 5
            },
            800,
            Laya.Ease.sineOut
        );
    }

    /**
     * 败北粒子特效（可选）
     */
    private playDefeatParticles(): void {
        // 这里可以添加粒子效果，比如灰尘、碎片等
        // 由于没有具体的粒子系统，这里用简单的图形效果代替

        for (let i = 0; i < 8; i++) {
            const particle = new Laya.Sprite();
            particle.graphics.drawCircle(0, 0, 3, "#888888");
            particle.x = this.boss.x + (Math.random() - 0.5) * 100;
            particle.y = this.boss.y + (Math.random() - 0.5) * 50;
            this.addChild(particle);

            // 粒子飞散效果
            Laya.Tween.to(
                particle,
                {
                    x: particle.x + (Math.random() - 0.5) * 200,
                    y: particle.y + Math.random() * 100 + 50,
                    alpha: 0,
                    scaleX: 0,
                    scaleY: 0
                },
                1000 + Math.random() * 500,
                Laya.Ease.quadOut,
                Laya.Handler.create(this, () => {
                    particle.removeSelf();
                })
            );
        }
    }

    onDisable(): void {
        this.hasResult = false;
        Laya.timer.clearAll(this);
    }
}
