const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { SettingRateDialogBase } from "./SettingRateDialog.generated";
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { ComUtil } from "../../utils/ComUtil";
import ClubManager from "../../global/ClubManager";
import GameLanguageMgr from "../../common/GameLanguageMgr";

@regClass('T4HZSfZ+Ry6DwwvmwW29RA==')
export class SettingRateDialog extends SettingRateDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private addL: number = 1;
    private maxValue: number = 5;
    private minValue: number = 15;
    data: any;
    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_plus.clickHandler = new Laya.Handler(this, this.handleClickBtn, [this.btn_plus]);
        this.btn_reduce.clickHandler = new Laya.Handler(this, this.handleClickBtn, [this.btn_reduce]);
        this.btn_ok.on(Laya.Event.CLICK, this, this.onComfirm);
        // this.btn_close.on(Laya.Event.CLICK, this, this.close);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SET_COMMISSION, this, this.onSetCommissionResponse);
    }

    public setOpenData(data: string[]) {
        this.data = data;
        if (!data) return;
        let rate = data[6];
        this.playerIcon.headSkin = data[2];
        // let clubData = SheetDataManager.getClubById(GlobalDataManager.clubType);
        // 使用ClubManager中保存的佣金比例
        let profitRatio = ClubManager.getProfitRatio();
        this.maxValue = parseFloat((profitRatio * 100).toFixed(3)) - 0.1;
        // this.minValue = clubData.referalCommission;
        this.addL = parseFloat(ComUtil.multiplyWithPrecision(parseFloat(rate), 100));//换算百分比
        this.minValue = this.addL;
        this.maxValue = Math.max(this.minValue,this.maxValue);//不能比最小的比例小
        this.btn_ok.disabled = this.minValue == this.maxValue;

        // 将数字处理为最多保留一位小数，没有小数则不保留
        const formattedNumber = this.addL % 1 === 0 ? this.addL.toFixed(0) : this.addL.toFixed(1);
        this.tf_rateNum.text = `${formattedNumber} %`;
        // console.log("data", data);
        const name = data[3];
        this.tf_msg.text = GameLanguageMgr.getLanguage(77, name,formattedNumber);
        let maxLab = this.maxValue % 1 === 0 ? this.maxValue.toFixed(0) : this.maxValue.toFixed(1);
        this.tf_tip1.text = GameLanguageMgr.getLanguage(76,formattedNumber,maxLab);
        this.tf_tip2.text = GameLanguageMgr.getLanguage(78);
    }

    /**
     * 请求设置分成比例
     */
    private onComfirm(): void {
        const cmdId = com.snake.socket.MessageType.MSG_SET_COMMISSION;
        const rate = Number(ComUtil.divideWithPrecision(this.addL, 100))
        const requestData = com.snake.socket.CS_SET_COMMISION.fromObject({
            addr: this.data[0],
            rate: rate
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 处理设置分成比例响应
     */
    private onSetCommissionResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 移除事件监听
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SET_COMMISSION, this, this.onSetCommissionResponse);

        var msgBody: com.snake.socket.CS_SET_COMMISION = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.CS_SET_COMMISION);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            let data = { roleId: this.data[0], rateValue: msgBody.rate }
            Signal.event(GameEvent.EVENT_CHANGE_CLUB_RATE, data);
            this.close();
        }
    }

    /**
     * 加减按钮点击事件
     */
    private handleClickBtn(currentTarget: Laya.Button): void {
        switch (currentTarget) {
            //--按钮
            case this.btn_reduce:
                {
                    //限制边界
                    if (this.addL > this.minValue) {
                        this.addL = parseFloat((this.addL - 0.1).toFixed(1));
                    }
                    this.setItemNum();
                }
                break;
            //++按钮
            case this.btn_plus:
                {
                    //限制边界
                    if (this.addL < this.maxValue) {
                        this.addL = parseFloat((this.addL + 0.1).toFixed(1));
                    }
                    this.setItemNum();
                }
                break;
        }
    }

    /**
     * 更新商品数量显示
     * 将当前的商品数量(addL)设置到数量输入框(tf_num)中
     */
    private setItemNum() {
        // 将数字处理为最多保留一位小数，没有小数则不保留
        const formattedNumber = this.addL % 1 === 0 ? this.addL.toFixed(0) : this.addL.toFixed(1);
        this.tf_rateNum.text = `${formattedNumber} %`;
    }

    onDisable(): void {
        this.btn_ok.off(Laya.Event.CLICK, this, this.onComfirm);
        // this.btn_close.off(Laya.Event.CLICK, this, this.close);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SET_COMMISSION, this, this.onSetCommissionResponse);
    }
}
