const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { JoinClubRoomDialogBase } from "./JoinClubRoomDialog.generated";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import EnterRoomManager from "../hall/EnterRoomManager";
import { TokenData } from "../../data/dto/TokenData";
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";
import GlobalDataManager from "../../global/GlobalDataManager";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import NoticeMgr from "../notice/NoticeMgr";
import { RoomVo } from "../../data/vo/pack/RoomVo";
import { EnumMatch } from "../../data/enumData/EnumMatch";

@regClass('ONfjH328RXe+7G3/K7WK1Q==')
export class JoinClubRoomDialog extends JoinClubRoomDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private roomVo: RoomVo;
    private isEntering: boolean = false; // 添加进入对战状态标记

    public constructor() {
        super();
    }

    onEnable(): void {
        this.initEvents();
        this.backLayer.alpha = 0;
        this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 0.7 }, 200, Laya.Ease.linearIn);
    }

    onDisable(): void {
        this.removeEvents();

        // 清除可能存在的定时器
        Laya.timer.clearAll(this);

        // 仅在未进入游戏时，调用MainScene的requestMailData方法
        if (!this.isEntering) {
            this.requestMainSceneMailData();
        }
    }

    /**
     * 对话框关闭时，调用MainScene的requestMailData方法
     * 确保在JoinClubRoomDialog关闭后能够显示邮件提醒
     */
    private requestMainSceneMailData(): void {
        // 使用Signal.event触发事件
        Signal.event(GameEvent.EVENT_REQUEST_MAIL_DATA);
    }

    /**
     * 初始化事件监听
     */
    private initEvents(): void {
        this.btn_font.on(Laya.Event.CLICK, this, this.onEnterMatch);
        this.backLayer.on(Laya.Event.CLICK, this, this.closeDialog);
        this.btn_watch.on(Laya.Event.CLICK, this, this.onWatchMatch);
        this.btn_invite.on(Laya.Event.CLICK, this, this.onInviteClick);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_QUERY_TOKEN, this, this.onRequestCoinInfoComplete);
    }

    /**
     * 移除事件监听
     */
    private removeEvents(): void {
        this.btn_font.off(Laya.Event.CLICK, this, this.onEnterMatch);
        this.backLayer.off(Laya.Event.CLICK, this, this.closeDialog);
        this.btn_watch.off(Laya.Event.CLICK, this, this.onWatchMatch);
        this.btn_invite.off(Laya.Event.CLICK, this, this.onInviteClick);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_QUERY_TOKEN, this, this.onRequestCoinInfoComplete);
    }

    /**
     * 对战按钮点击事件
     */
    private onEnterMatch(): void {
        if (!this.roomVo) return;
        if (!this.tokenData) return;

        // 设置状态为true，防止连点和确保关闭时不调用邮件请求
        this.isEntering = true;
        const ticketType = parseInt(this.roomVo.symbolId); // symbolId作为ticketType
        const ticketAmount = parseFloat(this.roomVo.cost); // cost作为ticketAmount
        const roomNo = this.roomVo.id; // 房间ID
        var symbol = this.tokenData.symbol;
        if (this.roomVo.arenaType == EnumMatch.ARENA_TYPE_MATCH) {
            //比赛模式
            EnterRoomManager.goMatchArenaScene(EnumMatch.ROOM_ID_MATCH, roomNo, symbol, this.roomVo.raceId);
        } else {
            //俱乐部模式
            EnterRoomManager.goCLubArenaScene(EnumMatch.ROOM_ID_JULEBU, ticketType, ticketAmount, roomNo, symbol);
        }

        // 3秒后恢复状态
        Laya.timer.once(3000, this, () => {
            this.isEntering = false;
        });
    }

    /**
     * 观战按钮点击事件
     */
    private onWatchMatch(): void {
        if (!this.roomVo) return;

        // 设置状态为true，防止连点和确保关闭时不调用邮件请求
        this.isEntering = true;

        //  const ticketType = parseInt(this.roomInfo[2]); // symbolId作为ticketType
        //  const ticketAmount = parseFloat(this.roomInfo[3]); // cost作为ticketAmount
        const roomNo = this.roomVo.id; // 房间ID
        if (this.roomVo.arenaType == EnumMatch.ARENA_TYPE_MATCH) {
            //比赛模式
            EnterRoomManager.watchPvpArenaScene(EnumMatch.ROOM_ID_MATCH, roomNo);
        } else {
            EnterRoomManager.watchPvpArenaScene(EnumMatch.ROOM_ID_JULEBU, roomNo);
        }

        // 3秒后恢复状态
        Laya.timer.once(3000, this, () => {
            this.isEntering = false;
        });
    }

    /**
     * 请求资产信息
     */
    public requestCoinInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_QUERY_TOKEN;
        HallWebSocket.send(cmdId);
    }

    tokenData: TokenData;

    /**
     * 显示购买页信息
     * @param data 参数
     */
    public async setOpenData(_roomVo: RoomVo): Promise<void> {
        // 检查URL参数中是否有clubroom信息
        const urlParams = new URLSearchParams(window.location.search);
        const clubRoomParam = urlParams.get("clubroom");
        this.roomVo = _roomVo;
        if (clubRoomParam) {
            try {
                // 尝试解析JSON格式的clubroom参数
                const parsedRoomInfo = JSON.parse(clubRoomParam);
                console.log("从URL参数获取俱乐部房间信息:", parsedRoomInfo);

                // 使用URL参数中的房间信息
                _roomVo = parsedRoomInfo;

                // 清除URL参数，防止刷新页面时重复打开
                if (window.history && window.history.replaceState) {
                    // 获取当前URL
                    const currentUrl = new URL(window.location.href);
                    // 只删除clubroom参数，保留其他参数
                    currentUrl.searchParams.delete("clubroom");
                    // 更新URL，不改变其他参数
                    window.history.replaceState({}, document.title, currentUrl.toString());
                }
            } catch (error) {
                console.error("解析URL俱乐部房间参数失败:", error);
            }
        }

        // 检查是否能获取到资产信息
        if (!AssetManager.getTokenData()) {
            // 如果拿不到资产信息，先注册监听，然后请求资产信息
            console.log("未获取到资产信息，正在请求资产信息...");

            // 监听资产信息返回事件
            Signal.on(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestCoinInfoComplete, [_roomVo]);

            // 请求资产信息
            AssetManager.requestCoinInfo();
        } else {
            // 如果已经有资产信息，直接设置房间信息
            this.setRoomInfo();
        }
    }

    /**
     * 资产信息请求完成回调
     * @param roomInfo 房间信息
     */
    private onRequestCoinInfoComplete(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 移除监听
        Signal.off(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestCoinInfoComplete);

        // 设置房间信息
        this.setRoomInfo();
    }

    private setRoomInfo(): void {
        // 保留原方法，目前未实现
        if (this.roomVo) {
            console.log(this.roomVo);
            const ticketType = parseInt(this.roomVo.symbolId); // symbolId作为ticketType
            const ticketAmount = parseFloat(this.roomVo.cost); // cost作为ticketAmount
            let symbolData = AssetManager.getTokenDataBySyId(ticketType);
            if (symbolData) {
                this.img_coin.skin = GameResourceManager.getCurrencyIcon(symbolData.symbol);
            }
            this.tf_number.text = String(ticketAmount);
            this.tokenData = AssetManager.getTokenData().find((item) => item.symbolId == ticketType);
            if (AssetManager.getTokenData() && this.tokenData) {
                this.tf_coin.text = this.tokenData.symbol;
            }

            if (this.roomVo.arenaType == EnumMatch.ARENA_TYPE_MATCH) {
                this.alertTitle.text = "Tournament";
                this.box_amount.visible = false;
                this.btn_font.y -= 100;
            }
        }
    }

    private onInviteClick(): void {
        if (!this.roomVo) return;

        // 获取当前的 URL
        const currentUrl = new URL(window.location.href);

        // 解析 URL 参数
        const params = currentUrl.searchParams;

        // 删除可能存在的旧clubroom参数
        if (params.has("clubroom")) {
            params.delete("clubroom");
        }

        // 确保链接中包含scene=startup参数
        if (!params.has("scene")) {
            params.append("scene", "startup");
        } else {
            params.set("scene", "startup");
        }

        // 创建包含房间信息的对象
        this.roomVo.club = GlobalDataManager.playerDto.club;

        // 添加clubroom参数
        params.append("clubroom", JSON.stringify(this.roomVo));

        // 更新 URL
        currentUrl.search = params.toString();
        const inviteUrl = currentUrl.toString();

        doCopy(inviteUrl);
        NoticeMgr.notice(GameLanguageMgr.getLanguage(19)); //复制成功
    }

    /**
     * 关闭对话框
     */
    private closeDialog(): void {
        this.close();
    }
}
