    private createPublicClientTransport(chain: any) {
        if (chain.id == bsc.id) {
            var rpcUrls = [
                "https://56.rpc.thirdweb.com/97290ce73206a64be2b6f3a833ad24f8",
                "https://rpc.ankr.com/bsc/e0e2ec06f5aad07e27fa59035107d1f363422c875153439ced83f39f65ada95f"
            ];
            return fallback(
                rpcUrls.map((url) => http(url, { timeout: 10000 })),
                { retryCount: 3, retryDelay: 500 }
            );
        } else {
            return http();
        }
    }

