    /**
     * TON钱包连接和签名功能
     * @description 连接TON钱包并进行消息签名
     */
    public async connectTonWallet(): Promise<any> {
        const toxStorageTelegram = localStorage.getItem("TOX-COOKIE-CODE_Telegram");
        const str = ETHUtils.decodeTon(toxStorageTelegram);
        const array = ETHUtils.signTelegramArray(str);
        console.log("array===>", array);

        // this.goTonWallet();
        // return;
        // 使用TonConnectUI并指定正确的DOM元素
        this.tonConnectUI = await new TonConnectUI({
            manifestUrl: "https://snake.cryptoarena.io/tonconnect-manifest.json",
            buttonRootId: "ton-connect"
        });
        const tonConnectElement = document.getElementById("ton-connect");
        if (tonConnectElement) {
            tonConnectElement.style.display = "none";
        }

        // 获取签名信息里的address，单独存储，因为登录成功后要清楚签名信息缓存
        if (array?.address) {
            CookieUtil.setCookie("TOX_Telegram_Address", array?.address);
        }
        let TOX_Telegram_Address = CookieUtil.getCookie("TOX_Telegram_Address");
        console.log("TOX_Telegram_Address", TOX_Telegram_Address);
        const toxTelegramAddress = decodeURIComponent(CookieUtil.getCookie("TOX_Telegram_Address"));
        this.walletAddressTon = toxTelegramAddress;
        // 注册状态变更监听器
        this.tonConnectUI.onStatusChange(async (walletInfo) => {
            if (walletInfo && walletInfo.account) {
                if (walletInfo.account.address !== toxTelegramAddress) {
                    this.goTonWallet();
                }
            }
        });

        let token = CookieUtil.getCookie("TOX-CODE_TON-TOKEN"); // 获取cookies里toke

        if (array.type === "2") {
            // Telegram登录
            if (token) {
                // 没有签名信息逻辑（缓存里钱包地址用 getTokenTonStrByVersion 获取，是没转义的）
                // 先判断缓存里面有没token和address
                if (token && toxTelegramAddress) {
                    token = ETHUtils.decodeTon(token); // 解码保存的获取token代码
                    let codes = token.split("&"); // 分割各个获取token组件
                    // 从本地存储获取登录令牌和获取token代码

                    // 分解获取token组件
                    // time = parseFloat(codes[0]); // 时间戳
                    let remeberToken = codes[1]; // // 上次记住的token
                    let remeberUrl = codes[2]; // // 上次记住的url
                    let expireTime = codes[3]; // // 上次记住token有效日期（毫秒）
                    const isTimeValid = TimeUtil.checkTimeValid2(Number(expireTime));
                    if (!isTimeValid) {
                        CookieUtil.deleteCookie("TOX-CODE_TON-TOKEN");
                        this.goTonWallet();
                        return;
                    }
                    console.log(this.walletAddress);
                    this.walletAddress = ETHUtils.changeTonAddress(toxTelegramAddress);
                    console.log("remeberUrl===>", remeberUrl);
                    console.log("remeberToken===>", remeberToken);
                    HallWebSocket.wsUrl = remeberUrl;
                    this.token = remeberToken;
                    // HallWebSocket.connect();
                    return;
                }
            } else {
                this.tonSignLogin(array as any);
                return;
            }
        } else if (array.type === "1") {
            // GlobalDataManager.isTourist = true;
            // 游客登录
            this.tonEvmSignLogin(array as any);
            return;
        }

        this.goTonWallet();
    }

    private goTonWallet() {
        if (this.isTronWebApp()) return;
        // 获取当前的 URL
        const currentUrl = new URL(window.location.href);

        // 解析 URL 参数
        const params = currentUrl.searchParams;

        // 获取旧的 tv 参数
        const oldTv = params.get("tv");

        // 如果存在旧的 tv 参数，则将其删除
        if (oldTv) {
            params.delete("tv");
        }

        const newTv = 2; //版本号，防止cdn缓存

        // 添加新的 tv 参数
        params.append("tv", newTv + "");

        const searchParams = params.toString(); // 如"scene=startup&tv=1&lan=zh-cn"

        const signUrl = `./telegramConnect/index.html?${searchParams}`;
        // const signUrl = `${currentUrl.origin}/telegramConnect${searchParams}`;
        // alert(searchParams);
        window.location.href = signUrl;
    }

