    /**
     * 查询TON链上的代币余额
     * @description 通过TON API查询指定地址的代币余额
     * @param address 钱包地址
     * @param tokenAddress 代币合约地址
     * @returns 返回代币余额，如果查询失败则返回0
     */
    public async fetchTonTokenBalance(address: string, tokenAddress: string): Promise<number> {
        console.log("fetchTonTokenBalance11111");
        if (!address || !tokenAddress) {
            console.error("查询代币余额失败: 地址或代币合约地址为空");
            return 0;
        }

        try {
            // 使用TON API查询代币余额
            const response = await fetch(`https://tonapi.io/v2/accounts/${address}/jettons`);
            const data = await response.json();
            console.log("TON代币数据 ===>", data);
            console.log("fetchTonTokenBalance22222");

            let originTokenAddress = ETHUtils.revertTonAddress(tokenAddress);
            console.log("originTokenAddress ===>", originTokenAddress);

            // 在返回的代币列表中查找指定代币
            if (data && data.balances) {
                // 遍历balances数组，找到匹配jetton.address的项目
                const tokenItem = data.balances.find(
                    (item: any) =>
                        item.jetton &&
                        (item.jetton.address.toLowerCase() === originTokenAddress.toLowerCase() ||
                            item.jetton.address.toLowerCase() === tokenAddress.toLowerCase())
                );
                console.log("fetchTonTokenBalance3333", tokenItem);

                if (tokenItem) {
                    // 获取余额和精度
                    const balance = tokenItem.balance;
                    const decimals = tokenItem.jetton.decimals || 9;
                    const balanceInToken = Number(balance) / Math.pow(10, decimals);
                    console.log(`${tokenItem.jetton.symbol || "代币"} 余额 ===> ${balanceInToken}`);
                    return balanceInToken;
                } else {
                    console.log(`未找到合约地址为 ${tokenAddress} 或 ${originTokenAddress} 的代币`);
                }
            }

            return 0;
        } catch (error) {
            console.error("查询TON代币余额失败:", error);
            return 0;
        }
    }

    /**
     * 检查是否在Telegram WebApp中
     * @returns
     */
    public isTelegramWebApp(): boolean {
        // return true;
        try {
            // 判断是否在电报内置浏览器中（即 navigator.userAgent 包含 'Telegram' 字样）

            var telegramWebviewProxy = (window as any).TelegramWebviewProxy; //IOS
            console.log(`IOS: window.TelegramWebviewProxy: ${telegramWebviewProxy}`);
            var TelegramWebview = (window as any).TelegramWebview; //Andriod
            console.log(`Andriod: window.TelegramWebview: ${TelegramWebview}`);
            console.log(`======== END ======`);
            if (telegramWebviewProxy) {
                return true;
            }

            if (TelegramWebview) {
                return true;
            }

            const urlParams = new URLSearchParams(window.location.search);
            if (typeof navigator !== "undefined" && navigator.userAgent && navigator.userAgent.indexOf("Telegram") !== -1) {
                return true;
            }
            if (GameSetting.vType != 0) {
                if (typeof (window as any)["ethereum"] === "undefined") {
                    return true;
                }
            }

            // 检查Telegram WebApp对象是否存在
            if (typeof window === "undefined" || !(window as any).Telegram || !(window as any).Telegram.WebApp) {
                return false;
            }

            // 检查Telegram WebApp特有的属性和方法
            const webApp = (window as any).Telegram.WebApp;

            // 验证initData属性
            if (!webApp.initData || typeof webApp.initData !== "string") {
                return false;
            }

            // 验证initDataUnsafe对象
            if (!webApp.initDataUnsafe || typeof webApp.initDataUnsafe !== "object") {
                return false;
            }

            // 验证常见的WebApp方法
            if (typeof webApp.close !== "function" || typeof webApp.expand !== "function" || typeof webApp.ready !== "function") {
                return false;
            }

            return true;
        } catch (e) {
            console.error("检测Telegram环境时出错:", e);
            return false;
        }
    }

    private isTronWebApp(): boolean {
        // 判断是否存在 tronWeb 或 tronLink
        if ((window as any).tronWeb || (window as any).tronLink || window.location.href.indexOf("utm_source=tronlink") != -1) {
            console.log("当前处于波场钱包环境中");
            return true;
        } else {
            console.log("当前环境可能不是波场钱包，或钱包未注入对象");
            return false;
        }
    }

