    /**
     * 获取波场链资产余额（TRX和TRC20代币）
     * @param tokenAddress 代币地址，为空或特定值时获取TRX余额
     * @param bankAddress 目标地址，不传则使用当前钱包地址
     * @returns 余额（以最小单位返回）
     */
    async getTronBalance(tokenAddress: any | String, bankAddress: any = undefined) {
        try {
            // 检查TronWeb是否可用
            if (!(window as any).tronWeb || !(window as any).tronWeb.ready) {
                console.error("TronWeb未准备就绪");
                return 0;
            }

            let targetAddress = this.walletAddress;
            if (bankAddress) {
                targetAddress = bankAddress;
            }

            // 如果没有目标地址，尝试获取当前钱包地址
            if (!targetAddress && (window as any).tronWeb.defaultAddress) {
                targetAddress = (window as any).tronWeb.defaultAddress.base58;
            }

            if (!targetAddress) {
                console.error("无法获取目标地址");
                return 0;
            }

            let balance;
            // 主链币TRX的情况（tokenAddress为空或为TRX标识地址）
            if (
                !tokenAddress ||
                tokenAddress === "T9yD14Nj9j7xAB4dbGeiX9h8unkKHxuWwb" ||
                tokenAddress === "0x0000000000000000000000000000000000000000"
            ) {
                // 获取TRX余额（返回单位为Sun，1 TRX = 1,000,000 Sun）
                balance = await (window as any).tronWeb.trx.getBalance(targetAddress);
            } else {
                // 获取TRC20代币余额
                try {
                    // const contract = await (window as any).tronWeb.contract().at(tokenAddress);
                    const trc20Abi = EthereumConfig.TRON_TRC20ABI;
                    const contract = await (window as any).tronWeb.contract(trc20Abi, tokenAddress);
                    balance = await contract.balanceOf(targetAddress).call();
                    // TRC20代币余额通常返回的是BigNumber或字符串
                    if (typeof balance === "object" && balance._hex) {
                        balance = (window as any).tronWeb.toBigNumber(balance._hex).toString();
                    } else if (typeof balance === "object" && balance.toString) {
                        balance = balance.toString();
                    }
                } catch (contractError) {
                    console.error("获取TRC20代币余额失败:", contractError);
                    return 0;
                }
            }

            console.log("getTronBalance 代币地址:", tokenAddress, "目标地址:", targetAddress, "余额:", balance);
            return balance || 0;
        } catch (error) {
            console.error("获取波场余额失败:", error);
            return 0;
        }
    }

    public getTronChainId(): Promise<number> {
        return new Promise((resolve, reject) => {
            try {
                if (!(window as any).tronWeb || !(window as any).tronWeb.ready) {
                    console.error("TronWeb未准备就绪");
                    resolve(2494104990); // 默认Shasta测试网
                    return;
                }

                // 获取当前网络的节点信息来判断链ID
                const nodeInfo = (window as any).tronWeb.fullNode;
                console.log("TronWeb节点信息:", nodeInfo);

                let chainId: number;

                // 根据节点URL判断网络类型和链ID
                if (nodeInfo.host.includes("api.trongrid.io") || nodeInfo.host.includes("mainnet") || GameSetting.vType == 2) {
                    chainId = 728126428; // 主网链ID
                } else if (nodeInfo.host.includes("api.shasta.trongrid.io") || nodeInfo.host.includes("shasta")) {
                    chainId = 2494104990; // Shasta测试网链ID
                } else {
                    chainId = 2494104990; // 默认使用Shasta测试网
                }

                console.log("波场链ID:", chainId);
                resolve(chainId);
            } catch (error) {
                console.error("获取波场链ID失败:", error);
                resolve(2494104990); // 默认Shasta测试网
            }
        });
    }
