    /**
     * 创建抛物线动画 - 优化版，更干脆的右侧弧线
     * @param block 方块
     * @param targetPos 目标位置
     * @param delay 延迟时间
     */
    private createParabolaAnimation(block: Laya.Sprite, targetPos: Laya.Point, delay: number, callBack: Function): void {
        const duration = 300 + Math.random() * 100; // 缩短到300-400ms，更快更干脆

        Laya.timer.once(delay * 1000, this, () => {
            // 计算起点和终点
            const startX = block.x;
            const startY = block.y;
            const endX = targetPos.x;
            const endY = targetPos.y;

            // 计算距离
            const deltaX = endX - startX;
            const deltaY = endY - startY;
            const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

            // 更干脆的控制点设置
            const controlX = Math.max(startX, endX) + Math.min(300, distance * 0.8); // 根据距离动态调整
            const controlY = Math.min(startY, endY) - Math.abs(deltaX) * 0.3; // 高度基于水平距离

            // 使用缓动函数让动画更干脆
            let progress = 0;
            const frameTime = 16; // 60fps
            const totalFrames = duration / frameTime;
            const progressStep = 1 / totalFrames;

            const animate = () => {
                progress += progressStep;
                if (progress >= 1) {
                    progress = 1;
                    block.pos(endX, endY);
                    this.onBlockHit(block, endX, endY);
                    if (callBack) {
                        callBack();
                    }
                    return;
                }

                // 使用三次方缓动让前半段慢，后半段快，更干脆
                const easedProgress = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 3) / 2;

                // 二次贝塞尔曲线
                const t = easedProgress;
                const mt = 1 - t;

                const x = mt * mt * startX + 2 * mt * t * controlX + t * t * endX;
                const y = mt * mt * startY + 2 * mt * t * controlY + t * t * endY;

                block.pos(x, y);

                // 基于速度的旋转，后半段转得更快
                const rotationSpeed = progress < 0.5 ? 2 : 8;
                block.rotation += rotationSpeed;

                Laya.timer.once(frameTime, this, animate);
            };

            animate();
        });
    }

