    // 在类中添加堆叠计数器和对象池
    private damageStackCount: number = 0;
    private damageLabelPool: Laya.Label[] = [];
    private damageLabels: Laya.Label[] = [];

    /**
     * 显示伤害数字（优化版）
     * @param targetGlobalPos 目标全局位置
     * @param damage 伤害值
     * @param isCritical 是否为暴击
     */
    private showDamageNumber(targetGlobalPos: Laya.Point, damage: number, isCritical: boolean = false): void {
        const endLocalP = this.owner.bossBar.bossContainer.globalToLocal(targetGlobalPos, true);

        // 使用对象池获取标签（优化性能）
        let damageLabel: Laya.Label;
        if (this.damageLabelPool.length > 0) {
            damageLabel = this.damageLabelPool.pop()!;
            damageLabel.visible = true;
            damageLabel.alpha = 1;
            damageLabel.scale(1, 1);
        } else {
            damageLabel = new Laya.Label();
            damageLabel.fontSize = 24;
            damageLabel.stroke = 2;
            damageLabel.strokeColor = "#000000";
            damageLabel.bold = true;
            damageLabel.width = 100;
            damageLabel.align = "center";
            damageLabel.anchorX = 0.5;
            damageLabel.anchorY = 0.5;
        }

        // 设置伤害文本和样式
        damageLabel.text = `-${damage}`;

        if (isCritical) {
            damageLabel.color = "#FFD700"; // 金色暴击
            damageLabel.fontSize = 32;
            damageLabel.strokeColor = "#8B4513"; // 深棕色描边
            damageLabel.filters = [new Laya.GlowFilter("#FF4500", 8, 0, 0)]; // 添加发光效果
        } else {
            damageLabel.color = "#FF5555"; // 亮红色
            damageLabel.fontSize = 24;
            damageLabel.strokeColor = "#000000"; // 黑色描边
            damageLabel.filters = null;
        }

        // 计算堆叠偏移（每层增加45像素高度）
        const stackOffset = this.damageStackCount * 45;
        this.damageStackCount = (this.damageStackCount + 1) % 6; // 限制最大堆叠层数

        // 设置初始位置（包含随机水平偏移和垂直堆叠）
        const randomX = Tool.getRandInRound(-40, 40);
        damageLabel.pos(endLocalP.x + randomX, endLocalP.y - 25 - stackOffset);
        this.owner.bossBar.bossContainer.addChild(damageLabel);

        // 伤害数字动画 - 增强版
        // 第一阶段：弹跳动画
        Laya.Tween.to(
            damageLabel,
            {
                y: damageLabel.y - 30 - stackOffset,
                scaleX: isCritical ? 1.8 : 1.3,
                scaleY: isCritical ? 1.8 : 1.3
            },
            200,
            Laya.Ease.backOut,
            null,
            0,
            false
        );

        // 第二阶段：上浮+渐隐动画
        Laya.Tween.to(
            damageLabel,
            {
                y: damageLabel.y - (isCritical ? 100 : 70) - stackOffset,
                alpha: 0
            },
            1300,
            Laya.Ease.circIn,
            Laya.Handler.create(this, () => {
                damageLabel.removeSelf();
                this.damageLabelPool.push(damageLabel); // 回收对象
                this.damageStackCount = Math.max(0, this.damageStackCount - 1);
            }),
            200
        );

        // 暴击特效
        if (isCritical) {
            // 暴击震动效果
            const originalX = damageLabel.x;
            Laya.Tween.to(
                damageLabel,
                { x: originalX - 5 },
                50,
                null,
                Laya.Handler.create(this, () => {
                    Laya.Tween.to(
                        damageLabel,
                        { x: originalX + 5 },
                        50,
                        null,
                        Laya.Handler.create(this, () => {
                            Laya.Tween.to(damageLabel, { x: originalX }, 50);
                        })
                    );
                })
            );

            // 暴击粒子效果
            this.createCriticalEffect(endLocalP);
        }

        // 保存引用以便清理
        this.damageLabels.push(damageLabel);
    }

    /**
     * 创建暴击特效
     * @param pos 特效位置
     */
    private createCriticalEffect(pos: Laya.Point): void {
        const effectContainer = new Laya.Sprite();
        this.owner.bossBar.bossContainer.addChild(effectContainer);
        effectContainer.pos(pos.x, pos.y);

        // 创建粒子效果
        for (let i = 0; i < 8; i++) {
            const particle = new Laya.Sprite();
            particle.graphics.drawCircle(0, 0, 3, "#FFD700");
            effectContainer.addChild(particle);

            const angle = (i / 8) * Math.PI * 2;
            const distance = Math.random() * 30 + 20;

            Laya.Tween.to(
                particle,
                {
                    x: Math.cos(angle) * distance,
                    y: Math.sin(angle) * distance,
                    alpha: 0
                },
                500,
                Laya.Ease.circOut,
                Laya.Handler.create(this, () => {
                    particle.removeSelf();
                })
            );
        }

        // 移除特效容器
        Laya.timer.once(600, this, () => {
            effectContainer.removeSelf();
        });
    }

    /**
     * 清理所有伤害数字
     */
    public clearAllDamageNumbers(): void {
        this.damageStackCount = 0;
        this.damageLabels.forEach((label) => {
            Laya.Tween.killAll(label);
            label.removeSelf();
        });
        this.damageLabels = [];
    }
