    /**
     * 播放攻击音效
     * @param count 消除数量
     */
    private playAttackSound(count: number): void {
        // 根据消除数量播放不同音效
        if (count >= 6) {
            // 播放强力攻击音效
            SoundMgr.playSoundByName(SoundMgr.soundName_flyHit2);
        } else if (count >= 4) {
            // 播放普通攻击音效
            SoundMgr.playSoundByName(SoundMgr.soundName_flyHit1);
        }
    }

