const { regClass, property } = Laya;

@regClass('KeVc3rlySY2qk84Qs9MTYw==')
export default class StretchAnimation extends Laya.Script {
    owner: Laya.Sprite;

    /** @prop {name:autoStart, tips:"自动开始动画", type:boolean, default:true}*/
    @property({ type: "boolean" })
    public autoStart: boolean = true;

    /** @prop {name:stretchScale, tips:"拉伸幅度", type:number, default:1.15}*/
    @property({ type: "number" })
    public stretchScale: number = 1.15;

    /** @prop {name:compressScale, tips:"压缩幅度", type:number, default:0.9}*/
    @property({ type: "number" })
    public compressScale: number = 0.9;

    /** @prop {name:animationSpeed, tips:"动画速度", type:number, default:120}*/
    @property({ type: "number" })
    public animationSpeed: number = 120;

    /** @prop {name:loopInterval, tips:"循环间隔(毫秒)", type:number, default:2000}*/
    @property({ type: "number" })
    public loopInterval: number = 2000;

    private animationTween: Laya.Tween;
    private loopTimer: number;
    private dampingFactor: number = 0.75;
    private stretchCount: number = 5;

    constructor() {
        super();
    }

    onEnable(): void {
        if (this.autoStart && this.isButtonEnabled()) {
            this.startStretchAnimation();
        }
    }

    onDisable(): void {
        this.stopStretchAnimation();
    }

    /**
     * 检查按钮是否可用
     */
    private isButtonEnabled(): boolean {
        // 检查owner是否存在且可见
        if (!this.owner || !this.owner.visible) {
            return false;
        }

        // 检查是否有mouseEnabled属性且为true
        if ("mouseEnabled" in this.owner && !(this.owner as any).mouseEnabled) {
            return false;
        }

        // 检查是否有disabled属性且为false
        if ("disabled" in this.owner && (this.owner as any).disabled) {
            return false;
        }

        // 检查透明度，通常不可用的按钮会设置较低的透明度
        if (this.owner.alpha < 0.5) {
            return false;
        }

        return true;
    }

    /**
     * 开始拉伸动画
     */
    public startStretchAnimation(): void {
        if (!this.isButtonEnabled()) {
            return;
        }

        this.stopStretchAnimation();
        this.playStretchSequence();
    }

    /**
     * 停止拉伸动画
     */
    public stopStretchAnimation(): void {
        if (this.animationTween) {
            this.animationTween.clear();
            this.animationTween = null;
        }
        if (this.loopTimer) {
            Laya.timer.clear(this, this.playStretchSequence);
            this.loopTimer = null;
        }
        // 重置缩放
        if (this.owner) {
            this.owner.scaleX = 1;
            this.owner.scaleY = 1;
        }
    }

    /**
     * 播放拉伸序列
     */
    private playStretchSequence(): void {
        // 在每次播放前检查按钮状态
        if (!this.isButtonEnabled()) {
            this.stopStretchAnimation();
            return;
        }

        let currentStretch = 0;
        let currentScale = this.stretchScale;
        let currentCompress = this.compressScale;
        let currentDuration = this.animationSpeed;

        const playNextStretch = () => {
            // 在每次拉伸前检查按钮状态
            if (!this.isButtonEnabled()) {
                this.stopStretchAnimation();
                return;
            }

            if (currentStretch >= this.stretchCount) {
                // 动画序列完成，设置循环
                Laya.timer.once(this.loopInterval, this, this.playStretchSequence);
                // this.loopTimer = Laya.timer.once(this.loopInterval, this, this.playStretchSequence);
                return;
            }

            // 拉伸阶段
            this.animationTween = Laya.Tween.to(
                this.owner,
                {
                    scaleX: currentScale,
                    scaleY: currentCompress
                },
                currentDuration,
                Laya.Ease.sineOut,
                Laya.Handler.create(this, () => {
                    // 在还原前再次检查按钮状态
                    if (!this.isButtonEnabled()) {
                        this.stopStretchAnimation();
                        return;
                    }

                    // 还原阶段
                    this.animationTween = Laya.Tween.to(
                        this.owner,
                        {
                            scaleX: 1,
                            scaleY: 1
                        },
                        currentDuration * 0.6,
                        Laya.Ease.elasticOut,
                        Laya.Handler.create(this, () => {
                            // 准备下一次拉伸
                            currentStretch++;
                            currentScale = 1 + (currentScale - 1) * this.dampingFactor;
                            currentCompress = 1 - (1 - currentCompress) * this.dampingFactor;
                            currentDuration *= this.dampingFactor;

                            // 短暂停顿后继续
                            Laya.timer.once(50, this, playNextStretch);
                        })
                    );
                })
            );
        };

        playNextStretch();
    }

    /**
     * 手动触发一次拉伸动画
     */
    public triggerStretch(): void {
        if (!this.isButtonEnabled()) {
            return;
        }

        this.stopStretchAnimation();
        this.playStretchSequence();
    }

    /**
     * 设置动画参数
     */
    public setAnimationParams(stretchScale: number, compressScale: number, speed: number, interval: number): void {
        this.stretchScale = stretchScale;
        this.compressScale = compressScale;
        this.animationSpeed = speed;
        this.loopInterval = interval;
    }

    /**
     * 当按钮状态改变时调用此方法
     */
    public onButtonStateChanged(): void {
        if (this.isButtonEnabled()) {
            if (this.autoStart && !this.animationTween && !this.loopTimer) {
                this.startStretchAnimation();
            }
        } else {
            this.stopStretchAnimation();
        }
    }
}
