    private requestRoleInfo(): void {
        // 定义常量
        const DEFAULT_HEAD_ID = "1"; // 设置默认头像ID

        // 获取玩家数据
        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto) {
            console.warn("Player data is not available");
            return;
        }

        // 请求玩家详细信息
        GlobalDataManager.requestPlayerInfo(playerDto.pid);
        // 请求邀请列表信息，替换原来的社区信息请求
        this.requestInviteList();

        this.startRequestClubInfo();
    }
    private updateRoleInfo(): void {
        // 定义常量
        const DEFAULT_HEAD_ID = "1"; // 设置默认头像ID

        // 获取玩家数据
        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto) {
            console.warn("Player data is not available");
            return;
        }
        // 更新基本信息
        this.updateBasicInfo(playerDto);

        // 更新邀请码信息
        this.updateReferralInfo(playerDto);

        // 更新国家信息
        this.updateCountryInfo(playerDto.country);

        // 更新钱包地址
        this.updateWalletAddress();

        // 更新头像
        this.updatePlayerIcon(playerDto.icon || DEFAULT_HEAD_ID);
    }

    /**
     * 请求邀请列表信息（用于获取邀请总数）
     */
    private requestInviteList(): void {
        const cmdId = com.snake.socket.MessageType.MSG_INVITE_LIST;
        const requestData = com.snake.socket.CS_INVITE_LIST.fromObject({
            pageNo: 1,
            pageSize: 1 // 只需要一条数据，主要是为了获取inviteCount
        });
        HallWebSocket.send(cmdId, requestData);
    }

