// OptCmd.ts

import CellModel from "./CellModel";
import { ANITIME } from "./ConstValue";

/**
 * 单元格命令基类
 */
export class CellCmd {
    playTime: number = 0; // 播放开始时间
    keepTime: number = 0; // 持续时间
}

// 单元格创建命令
export class CellCreate extends CellCmd {
    pos: Laya.Point; // 创建位置
    zIndex: number = -1; // 层级
}

// 单元格移动命令
export class CellMoveTo extends CellCmd {
    pos: Laya.Point; // 目标位置

    constructor(pos: Laya.Point) {
        super();
        this.pos = pos;
        this.keepTime = ANITIME.TOUCH_MOVE;
    }
}

// 单元格死亡命令
export class CellDie extends CellCmd {
    keepTime = ANITIME.DIE;
}

// 单元格抖动命令
export class CellShake extends CellCmd {
    keepTime = ANITIME.DIE_SHAKE;
}

// 单元格可见性命令
export class CellVisible extends CellCmd {
    isVisible: boolean; // 是否可见
}

// 单元格选择命令
export class CellSelect extends CellCmd {
    status: boolean; // 选择状态

    constructor(status: boolean) {
        super();
        this.status = status;
    }
}

// 单元格操作
export class CellOpt extends CellModel {
    cmdList: CellCmd[] = []; // 命令列表

    constructor(cell: CellModel) {
        super();
        Object.assign(this, cell);
    }

    /**
     * 添加命令
     * @param cmd 命令对象
     */
    addCellCmd(cmd: CellCmd): void {
        this.cmdList.push(cmd);
    }
}

/**
 * 特效命令基类
 */
export class EffectOpt {
    playTime: number; // 播放时间
    pos: Laya.Point; // 位置

    constructor(pos: Laya.Point) {
        this.pos = pos;
    }
}

// 消除特效
export class EffectCrush extends EffectOpt {
    step: number; // 消除步骤

    constructor(pos: Laya.Point, step: number) {
        super(pos);
        this.step = step;
    }
}

// 行爆炸特效
export class EffectRowBomb extends EffectOpt {}

// 列爆炸特效
export class EffectColBomb extends EffectOpt {}
export class EffectWrapBomb extends EffectOpt {}
export class EffectBirdBomb extends EffectOpt {
    id: number;
}

// 新增：格子转换特效
export class EffectCellTransform extends EffectOpt {
    fromStatus: string; // 原始状态
    toStatus: string; // 目标状态
    cellType: number; // 格子类型
    id: number;

    constructor(pos: Laya.Point, fromStatus: string, toStatus: string, cellType: number, id: number) {
        super(pos);
        this.fromStatus = fromStatus;
        this.toStatus = toStatus;
        this.cellType = cellType;
        this.id = id;
    }
}

/**
 * 操作类型枚举
 */
export enum OptType {
    Click, // 点击操作
    Swap, // 交换操作
    Crush // 消除操作
}

/**
 * 操作命令集合
 */
export default class Opt {
    cellOptList: CellOpt[] = []; // 单元格操作列表
    effectOptList: EffectOpt[] = []; // 特效操作列表
    curTime: number = 0; // 当前时间
    step: number; // 步骤计数
    optType: OptType; // 操作类型

    /**
     * 添加单元格操作命令
     * @param cellModel 单元格模型
     * @param cellCmd 单元格命令
     */
    addCellOptCmd(cellModel: CellModel, cellCmd: CellCmd): void {
        let cellOpt = this.getCellOpt(cellModel);
        if (!cellOpt) {
            cellOpt = new CellOpt(cellModel);
            this.cellOptList.push(cellOpt);
        }
        cellCmd.playTime = this.curTime;
        cellOpt.addCellCmd(cellCmd);
    }

    /**
     * 获取单元格操作
     * @param cellModel 单元格模型
     * @returns 单元格操作对象
     */
    getCellOpt(cellModel: CellModel): CellOpt | null {
        for (const cellOpt of this.cellOptList) {
            if (cellOpt.id === cellModel.id) {
                return cellOpt;
            }
        }
        return null;
    }

    /**
     * 添加特效操作
     * @param opt 特效操作
     */
    addEffectOptList(opt: EffectOpt): void {
        opt.playTime = this.curTime;
        this.effectOptList.push(opt);
    }

    /**
     * 增加时间
     * @param time 增加的时间
     */
    addTime(time: number): void {
        this.curTime += time;
        console.log("addTime = ", time);
    }
}
