    /**
     * 使用模型初始化视图（大Prefab+子Prefab结构，支持元素和障碍物任意组合）
     * @param model 单元格模型
     */
    async initWithModel(model: CellModel) {
        console.log(
            "initWithModel model: ",
            " type: " + model.type,
            " status: " + model.status,
            " x: " + model.x,
            " y: " + model.y,
            " startX: " + model.startX,
            " startY: " + model.startY,
            " isDeath: " + model.isDeath,
            " objectCount: " + model.objectCount
        );
        this.model = model;
        const x = model.startX;
        const y = model.startY;

        // 设置初始位置
        this.pos(CELL_WIDTH * (x - 0.5), CELL_HEIGHT * (y - 0.5));
        // 1. 清空节点
        this.elementNode.removeChildren();
        this.obstacleNode.removeChildren();

        // 2. 加载并挂载基本元素Prefab（从缓存取）
        var cellCfg: StageCellItem;
        if (model.type && model.type !== CELL_TYPE.EMPTY) {
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🔍 检查动物类型: type=${model.type}`);
            cellCfg = SheetDataManager.m_dicStageCells.get(model.type);
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📋 获取配置表数据:`, cellCfg);

            if (cellCfg) {
                ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📁 预制体路径: ${cellCfg.prefabPath}`);
                if (cellCfg.prefabPath) {
                    const prefab = DataManger.elementPrefabs[cellCfg.id];
                    ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🎭 获取预制体缓存: id=${cellCfg.id}`, prefab);

                    if (prefab) {
                        ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] ✅ 创建动物实例: ${cellCfg.name}`);
                        const instance: ElementCellView = prefab.create() as ElementCellView;
                        this.elementNode.addChild(instance);

                        // 如果子Prefab有initWithModel方法，则调用
                        if (typeof instance.initWithModel === "function") {
                            instance.initWithModel(model);
                        }
                        ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🎯 动物添加完成: elementNode子节点数=${this.elementNode.numChildren}`);
                    } else {
                        console.error(Quick.GetLogTime + `[ANIM_DEBUG] ❌ 预制体缓存为空: id=${cellCfg.id}`);
                        ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📦 当前elementPrefabs:`, Object.keys(DataManger.elementPrefabs));
                    }
                } else {
                    console.error(Quick.GetLogTime + `[ANIM_DEBUG] ❌ 预制体路径为空: type=${model.type}`);
                }
            } else {
                console.error(Quick.GetLogTime + `[ANIM_DEBUG] ❌ 配置表数据为空: type=${model.type}`);
                ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📚 当前配置表keys:`, Array.from(SheetDataManager.m_dicStageCells.keys));
            }
        } else {
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🚫 跳过空类型或EMPTY类型: type=${model.type}`);
        }
        // const cellCfg = CELL_TYPE_CONFIGS.find((cfg) => cfg.id === model.type);
        // if (cellCfg.prefabPath) {
        //     const prefab = DataManger.elementPrefabs[cellCfg.id];
        //     if (prefab) {
        //         const instance: ElementCellView = prefab.create() as ElementCellView;

        //         this.elementNode.addChild(instance);
        //         // 如果子Prefab有initWithModel方法，则调用
        //         if (typeof instance.initWithModel === "function") {
        //             instance.initWithModel(model);
        //         }
        //     }
        // }

        // 3. 加载并挂载障碍物Prefab（从缓存取）
        if (model.obstacle) {
            const obsCfg: StageCellItem = SheetDataManager.m_dicStageCells.get(model.obstacle.id);
            // const obsCfg = OBSTACLE_CONFIGS.find(
            //   (cfg) => cfg.id === model.obstacle.type
            // );
            if (obsCfg.prefabPath) {
                const prefab = DataManger.obstaclePrefabs[obsCfg.id];
                if (prefab) {
                    const instance: ObstacleCellView = prefab.create() as ObstacleCellView;
                    this.obstacleNode.addChild(instance);
                    // 如果子Prefab有initWithModel方法，则调用
                    if (typeof instance.initWithModel === "function") {
                        instance.initWithModel(model.obstacle);
                    }
                }
            }
        }
    }

