    /**
     * 执行动作序列（命令队列）
     * @param actions 动作列表
     */
    runActions(actions: any[]): void {
        // 获取目标元素的信息用于日志
        const targetName = this.name || "unknown";
        const targetPos = `(${this.x}, ${this.y})`;
        const modelInfo = this.model ? `type=${this.model.type} pos=(${this.model.x},${this.model.y})` : "no model";

        ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🎬 CellView.runActions开始: target=${targetName} pos=${targetPos} model=${modelInfo} actions数量=${actions.length}`);

        // 清除之前的动画，防止鸟交换等复杂操作时的动画冲突
        ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🧹 CellView清除动画: target=${targetName} pos=${targetPos}`);
        Laya.Tween.killAll(this, false);

        let ownerTween: Laya.Tween | null = null;
        var hasThen = false;

        // for (const action of actions) {

        for (let i = 0; i < actions.length; i++) {
            const action = actions[i];
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📝 CellView处理动作 ${i}: target=${targetName}`, action);

            if (action.delay) {
                hasThen = false;

                // 创建延迟动作
                ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] ⏰ CellView添加延迟动作: ${action.delay}ms target=${targetName}`);
                if (!ownerTween) {
                    ownerTween = Laya.Tween.create(this).delay(action.delay);
                } else {
                    ownerTween = ownerTween.chain().delay(action.delay);
                }
            } else if (action.moveTo) {
                hasThen = false;
                // 创建移动动作
                console.log(
                    Quick.GetLogTime +
                        `[ANIM_DEBUG] 🚀 CellView添加移动动作: target=${targetName} from${targetPos} to(${action.moveTo.x}, ${action.moveTo.y}) duration=${action.duration}ms`
                );

                if (!ownerTween) {
                    ownerTween = Laya.Tween.create(this).to("x", action.moveTo.x).to("y", action.moveTo.y).duration(action.duration);
                } else {
                    ownerTween = ownerTween.chain().to("x", action.moveTo.x).to("y", action.moveTo.y).duration(action.duration);
                }
            } else if (action.callback) {
                hasThen = true;
                // 创建回调动作
                ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 📞 CellView添加回调动作: target=${targetName}`);

                if (!ownerTween) {
                    ownerTween = Laya.Tween.create(this).then(action.callback);
                } else {
                    ownerTween = ownerTween.chain().then(action.callback);
                }
            } else if (action.shake) {
                hasThen = false;
                // 创建抖动动作
                ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] 🔄 CellView添加抖动动作: target=${targetName} duration=${action.duration}ms`);

                if (!ownerTween) {
                    ownerTween = Laya.Tween.create(this)
                        .to("rotation", 30)
                        .duration(action.duration / 6)
                        .chain()
                        .to("rotation", -60)
                        .duration(action.duration / 3)
                        .chain()
                        .to("rotation", 0)
                        .duration(action.duration / 6);
                } else {
                    ownerTween = ownerTween
                        .chain()
                        .to("rotation", 30)
                        .duration(action.duration / 6)
                        .chain()
                        .to("rotation", -60)
                        .duration(action.duration / 3)
                        .chain()
                        .to("rotation", 0)
                        .duration(action.duration / 6);
                }
            }
        }

        if (ownerTween) {
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] ✅ CellView动画序列创建完成并开始执行: target=${targetName}`);
            // 添加动画完成回调
            if (!hasThen) {
                ownerTween.then(this.cellTweenComplete, this);
            }
        } else {
            ////console.log(Quick.GetLogTime + `[ANIM_DEBUG] ❌ CellView没有创建任何动画: target=${targetName}`);
        }
    }
