    /**
     * 设置选中状态，代理到element和obstacle子Prefab
     */
    setSelect(flag: boolean): void {
        // 代理到elementNode子Prefab
        if (this.elementNode.numChildren > 0) {
            const element = this.elementNode.getChildAt(0) as ElementCellView;
            if (typeof element.setSelect === "function") {
                element.setSelect(flag);
            }
        }
        // 代理到obstacleNode子Prefab（如有需要）
        if (this.obstacleNode.numChildren > 0) {
            const obstacle = this.obstacleNode.getChildAt(0) as ObstacleCellView;
            if (typeof obstacle.setSelect === "function") {
                obstacle.setSelect(flag);
            }
        }
        // 推荐高亮动画
        if (flag) {
            // 停止之前的动画
            Laya.Tween.killAll(this, true);
            this.alpha = 1;
            this.scale(1, 1);
            // 闪烁动画：缩放+透明度交替
            Laya.Tween.to(
                this,
                { scaleX: 1.2, scaleY: 1.2, alpha: 0.7 },
                300,
                Laya.Ease.linearNone,
                Laya.Handler.create(this, () => {
                    Laya.Tween.to(this, { scaleX: 1, scaleY: 1, alpha: 1 }, 300, Laya.Ease.linearNone, null, 0, true);
                }),
                0,
                true
            );
        } else {
            Laya.Tween.killAll(this, true);
            this.alpha = 1;
            this.scale(1, 1);
        }
    }
    /**
     * 消除时缩小+变透明动画
     */
    playBirdGuangEffect(): void {
        if (this.elementNode.numChildren > 0) {
            DataManger.grid.addChildAt(this, 0);
            const element = this.elementNode.getChildAt(0) as ElementCellView;
            if (typeof element.playBirdGuangEffect === "function") {
                element.playBirdGuangEffect();
            }
        }
    }
