    /**
     * 更新障碍物显示状态
     * 根据模型的障碍物状态更新obstacleNode的显示
     */
    updateObstacleDisplay(): void {
        console.log(`[updateObstacleDisplay] 开始更新障碍物显示`);
        console.log(`[updateObstacleDisplay] this.model:`, this.model);
        console.log(`[updateObstacleDisplay] this.model.obstacle:`, this.model.obstacle);
        console.log(`[updateObstacleDisplay] this.model.id:`, this.model?.id);
        console.log(`[updateObstacleDisplay] this.model.x:`, this.model?.x);
        console.log(`[updateObstacleDisplay] this.model.y:`, this.model?.y);

        if (!this.model) {
            console.log(`[updateObstacleDisplay] model为空，返回`);
            return;
        }

        // 如果模型中没有障碍物，清空obstacleNode
        if (this.model.obstacle) {
            console.log(`[updateObstacleDisplay] 模型中没有障碍物，准备清空obstacleNode`);
            console.log(`[updateObstacleDisplay] obstacleNode子节点数:`, this.obstacleNode.numChildren);
            if (this.obstacleNode.numChildren > 0) {
                console.log(`[updateObstacleDisplay] 开始播放障碍物消除动画`);
                // 播放消除动画后移除
                const obstacle = this.obstacleNode.getChildAt(0) as ObstacleCellView;
                if (obstacle && typeof obstacle.playDieEffect === "function") {
                    console.log(`[updateObstacleDisplay] 调用障碍物的playDieEffect方法`);
                    obstacle.playDieEffect();
                } else {
                    console.log(`[updateObstacleDisplay] 障碍物没有playDieEffect方法，直接移除`);
                    // 如果没有动画方法，直接移除
                    this.obstacleNode.removeChildren();
                }
            } else {
                console.log(`[updateObstacleDisplay] obstacleNode已经没有子节点`);
            }
            this.model.obstacle = null;
        } else {
            console.log(`[updateObstacleDisplay] 模型中还有障碍物，不清空obstacleNode`);
            console.log(`[updateObstacleDisplay] 障碍物信息:`, this.model.obstacle);
        }
        // 如果需要添加新的障碍物，可以在这里扩展
    }
