import { Quick } from "./Quick";
import { EnumTime } from "../data/enumData/EnumTime";
import GameLanguageMgr from "../common/GameLanguageMgr";
import GameSetting from "../global/GameSetting";
import GlobalDataManager from "../global/GlobalDataManager";
export class TimeUtil {
    public static OneDaySceond: number = 24 * 3600;
    public static OneHourSceond: number = 3600;
    public static OneMiniuteSecond: number = 60;
    public constructor() {}

    /**
     * 将毫秒数格式化为"秒:毫秒"格式的字符串
     * @param totalMM 总毫秒数
     * @returns 格式化后的字符串，格式为"SS:MMM"，如"05:045"
     */
    public static formatMM(totalMM: number): string {
        if (totalMM <= 0) {
            return "00:000";
        }
        let _second: number, millisecon: number;
        _second = totalMM / 1000;
        millisecon = totalMM % 1000;
        let numberTime: string = "";
        if (_second <= 9) {
            numberTime += "0";
        }
        numberTime += Math.floor(_second);
        numberTime += ":";
        if (millisecon <= 9) {
            numberTime += "00";
        } else if (millisecon <= 99) {
            numberTime += "0";
        }
        numberTime += millisecon;
        return numberTime;
    }

    /**
     * 将秒数格式化为时分秒格式的字符串
     * @param totalsec 总秒数
     * @param _sign 分隔符，默认为":"
     * @param needHour 是否需要显示小时，默认为true
     * @returns 格式化后的字符串，当needHour为true时返回"HH:MM:SS"格式，否则返回"MM:SS"格式
     */
    public static format(totalsec: number, _sign: string = ":", needHour: boolean = true): string {
        if (totalsec <= 0) {
            return needHour ? "00:00:00" : "00:00";
        }

        let hours = 0;
        let minutes = 0;
        let seconds = 0;

        if (needHour) {
            // 需要小时显示：正常计算 H:M:S
            hours = Math.floor(totalsec / 3600);
            const remain = totalsec % 3600;
            minutes = Math.floor(remain / 60);
            seconds = Math.ceil(remain % 60);
        } else {
            // 不需要小时显示：将总秒数全部转换为分钟和秒
            minutes = Math.floor(totalsec / 60);
            seconds = Math.ceil(totalsec % 60);
        }

        // 处理秒数进位（当 seconds=60 时）
        if (seconds === 60) {
            seconds = 0;
            minutes += 1;

            // 如果需要小时显示，分钟进位到小时
            if (needHour) {
                if (minutes === 60) {
                    minutes = 0;
                    hours += 1;
                }
            }
        }

        // 格式化输出
        const parts: string[] = [];

        if (needHour) {
            parts.push(hours.toString().padStart(2, "0"));
        }

        parts.push(minutes.toString().padStart(2, "0"));
        parts.push(seconds.toString().padStart(2, "0"));

        return parts.join(_sign);
    }

    /**
     * 将秒数格式化为带天数的时间格式字符串
     * @param totalsec 总秒数
     * @param _sign 分隔符，默认为":"
     * @param needFlash 是否需要闪烁效果，当为true且秒数为奇数时，分隔符会变色
     * @returns 格式化后的字符串，当天数>=1时返回"D天 HH:MM"格式，否则返回"HH:MM:SS"格式
     */
    public static formatWithDay(totalsec: number, _sign: string = ":", needFlash: boolean = false): string {
        if (totalsec <= 0) {
            return "00:00";
        }
        let _second: number, _day: number, remain: number, _hours: number, _minute: number;
        _day = totalsec / 86400;
        remain = totalsec % 86400;
        _hours = remain / 3600;
        remain = remain % 3600;
        _minute = remain / 60;
        _second = remain % 60;
        let numberTime: string = "";
        if (_day >= 1) {
            numberTime = GameLanguageMgr.getLanguage(16, Math.floor(_day)) + " ";
            if (_hours <= 9) {
                numberTime += "0";
            }

            if (needFlash && _second % 2 != 0) {
                _sign = Quick.getColorText(_sign, "#412b20");
            }

            numberTime += Math.floor(_hours) + _sign;
            if (_minute <= 9) {
                numberTime += "0";
            }

            numberTime += Math.floor(_minute);
        } else {
            if (_hours <= 9) {
                numberTime += "0";
            }

            numberTime = Math.floor(_hours) + _sign;
            if (_minute <= 9) {
                numberTime += "0";
            }

            numberTime += Math.floor(_minute) + _sign;
            if (Math.ceil(_second) <= 9) {
                numberTime += "0";
            }

            numberTime += Math.ceil(_second);
        }
        return numberTime;
    }

    /**
     * 将毫秒数转换为秒的字符串
     * @param totalMs 总毫秒数
     * @returns 返回转换后的秒数字符串
     */
    public static formatWithSecondByMs(totalMs: number): string {
        return `${totalMs / 1000}`;
    }

    /**
     *
     * @param ms 时间格式
     * @returns
     */
    public static getTimeByMs(ms: number): string {
        let date: Date = new Date(ms);
        return date.getHours() + ":" + date.getMinutes() + ":" + date.getSeconds() + ":" + date.getMilliseconds();
    }

    /**
     * 将毫秒数转换为天时分秒毫秒格式的字符串(剩余时间格式)
     * @param totalMs 总毫秒数
     * @param _sign 时间单位之间的分隔符，默认为":"
     * @param needFlash 是否需要闪烁效果，当为true且秒数为奇数时，分隔符会变色
     * @returns 返回格式化后的时间字符串，格式为"D天 HH:MM:SS MMM"，如果天数小于1则不显示天数
     */
    public static formatWithDayByMs(totalMs: number, _sign: string = ":", needFlash: boolean = false): string {
        if (totalMs <= 0) {
            return "00:00";
        }
        let _msecond: number, _second: number, _day: number, remain: number, _hours: number, _minute: number;
        _day = totalMs / 86400000;
        remain = totalMs % 86400000;
        _hours = remain / 3600000;
        remain = remain % 3600000;
        _minute = remain / 60000;
        remain = remain % 60000;
        _second = remain / 1000;
        _msecond = remain % 1000;
        let numberTime: string = "";
        if (_day >= 1) {
            numberTime = GameLanguageMgr.getLanguage(16, Math.floor(_day)) + " ";
        }

        if (_hours <= 9) {
            numberTime += "0";
        }
        numberTime += Math.floor(_hours) + _sign;

        if (_minute <= 9) {
            numberTime += "0";
        }
        numberTime += Math.floor(_minute) + _sign;

        if (Math.ceil(_second) <= 9) {
            numberTime += "0";
        }
        numberTime += Math.floor(_second) + " ";
        numberTime += Math.ceil(_msecond);
        return numberTime;
    }

    /**
     * 将秒数按指定格式转换为时间数组
     * @param second 总秒数
     * @param formatType 时间格式字符串，默认为"HH-MM-SS"，可包含DD（天）、HH（时）、MM（分）、SS（秒），用"-"分隔
     * @returns 返回按格式转换后的时间数组，如[12,30,45]表示12时30分45秒
     */
    public static getTimeArray(second: number, formatType: string = "HH-MM-SS"): any[] {
        second = Math.max(0, second);
        if (formatType.indexOf("-") == -1) {
            return [];
        }
        let result: any[] = [];
        let types: any[] = formatType.split("-");
        for (let type of types) {
            if (type == "DD") {
                result.push(Math.floor(second / TimeUtil.OneDaySceond));
            } else if (type == "HH") {
                result.push(Math.floor((second % TimeUtil.OneDaySceond) / TimeUtil.OneHourSceond));
            } else if (type == "MM") {
                result.push(Math.floor((second % TimeUtil.OneHourSceond) / TimeUtil.OneMiniuteSecond));
            } else if (type == "SS") {
                result.push(second % TimeUtil.OneMiniuteSecond);
            }
        }
        return result;
    }

    /**
     * 根据时间戳获取Date对象
     * @param timeStamp 时间戳（毫秒）
     * @returns 返回对应时间戳的Date对象
     */
    public static getServerDate(timeStamp: number): Date {
        let date: Date = new Date(timeStamp);
        return date;
    }

    /**
     * 将时间戳格式化为指定格式的时间字符串
     * @param time 时间戳（毫秒）
     * @param formatType 时间格式字符串，默认为"YY-MT-DD HH:MM:SS"，支持的格式标识：
     *                  - YY: 年份
     *                  - MT: 月份（01-12）
     *                  - DD: 日期（01-31）
     *                  - HH: 小时（00-23）
     *                  - MM: 分钟（00-59）
     *                  - SS: 秒钟（00-59）
     * @param isUtc 是否使用UTC时间，默认为false使用本地时间
     * @returns 返回格式化后的时间字符串
     */
    public static formatTimeStamp(time: number, formatType: string = "YY-MT-DD HH:MM:SS", isUtc: boolean = false): string {
        let date: Date = TimeUtil.getServerDate(time);
        let formatStr: string = "";
        if (formatType.indexOf("YY") >= 0) {
            formatStr = (isUtc ? date.getUTCFullYear() : date.getFullYear()) + "";
            formatType = formatType.replace("YY", formatStr);
        }
        if (formatType.indexOf("MT") >= 0) {
            let month: number = (isUtc ? date.getUTCMonth() : date.getMonth()) + 1;
            if (month > 9) {
                formatStr = month + "";
            } else {
                formatStr = "0" + month;
            }
            formatType = formatType.replace("MT", formatStr);
        }
        if (formatType.indexOf("DD") >= 0) {
            let _date: number = isUtc ? date.getUTCDate() : date.getDate();
            if (_date > 9) {
                formatStr = _date + "";
            } else {
                formatStr = "0" + _date;
            }
            formatType = formatType.replace("DD", formatStr);
        }
        if (formatType.indexOf("HH") >= 0) {
            let hour: number = isUtc ? date.getUTCHours() : date.getHours();
            if (hour > 9) {
                formatStr = hour + "";
            } else {
                formatStr = "0" + hour;
            }
            formatType = formatType.replace("HH", formatStr);
        }
        if (formatType.indexOf("MM") >= 0) {
            let min: number = isUtc ? date.getUTCMinutes() : date.getMinutes();
            if (min > 9) {
                formatStr = min + "";
            } else {
                formatStr = "0" + min;
            }
            formatType = formatType.replace("MM", formatStr);
        }
        if (formatType.indexOf("SS") >= 0) {
            let sec: number = isUtc ? date.getUTCSeconds() : date.getSeconds();
            if (sec > 9) {
                formatStr = sec + "";
            } else {
                formatStr = "0" + sec;
            }
            formatType = formatType.replace("SS", formatStr);
        }
        return formatType;
    }

    /**
     * 格式化时间戳为指定语言的日期字符串
     * @param timestamp 时间戳（毫秒）
     * @param language 语言类型：'en'（英文）、'zh-Hant'（繁体）、'zh-Hans'（简体）
     * @returns 格式如 "Friday 16:00 PM" 的字符串
     */
    public static formatTimeStampWithWeek(timestamp: number): string {
        var m_strLanguage = GlobalDataManager.m_strLanguage;
        var language: string = "en";
        if (m_strLanguage == 6) {
            language = "zh-Hant"; //繁体
        } else if (m_strLanguage == 7) {
            language = "zh-Hans"; //简体
        }
        const date = new Date(timestamp);

        // 星期映射表
        const weekdays = {
            en: ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
            "zh-Hant": ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"],
            "zh-Hans": ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"]
        };

        // 上下午映射表
        const periodMap = {
            en: { am: "AM", pm: "PM" },
            "zh-Hant": { am: "上午", pm: "下午" },
            "zh-Hans": { am: "上午", pm: "下午" }
        };

        // 获取星期几（0-6）
        const dayIndex = date.getDay();
        const weekday = weekdays[language as keyof typeof weekdays][dayIndex];

        // 获取小时和分钟
        const hours = date.getHours();
        const minutes = date.getMinutes().toString().padStart(2, "0");

        // 判断上下午并获取对应标识
        const period = hours < 12 ? periodMap[language as keyof typeof periodMap].am : periodMap[language as keyof typeof periodMap].pm;

        // 组合结果（保持24小时制的小时显示）
        return `${weekday} ${hours.toString().padStart(2, "0")}:${minutes} ${period}`;
    }

    /**
     * 将时间戳格式化为标准格式的时间字符串
     * @param time 时间戳（毫秒）
     * @param formatType 时间格式字符串，默认为"YY-MT-DD HH:MM:SS"，使用parseTimeDetail方法处理各个时间单位
     * @returns 返回格式化后的时间字符串
     */
    public static formatTimeStamps(time: number, formatType: string = "YY-MT-DD HH:MM:SS"): string {
        let date: Date = TimeUtil.getServerDate(time);
        let formatStr: string = formatType;
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "YY", false);
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "MT", false);
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "DD", false);
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "HH", true);
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "MM", true);
        formatStr = TimeUtil.parseTimeDetail(date, formatStr, "SS", true);
        return formatStr;
    }

    /**
     * 处理时间格式化的内部方法
     * @param date Date对象
     * @param formatStr 待处理的格式字符串
     * @param signType 时间单位标识（YY/MT/DD/HH/MM/SS）
     * @param needZero 是否需要补零，为true时个位数前补0
     * @returns 返回处理后的格式字符串
     */
    private static parseTimeDetail(date: Date, formatStr: string, signType: string, needZero: boolean): string {
        if (formatStr.indexOf(signType) >= 0) {
            let secStr: string;
            let sec: number;
            if (signType == "YY") {
                sec = date.getFullYear();
            } else if (signType == "MT") {
                sec = date.getMonth() + 1;
            } else if (signType == "DD") {
                sec = date.getDate();
            } else if (signType == "HH") {
                sec = date.getHours();
            } else if (signType == "MM") {
                sec = date.getMinutes();
            } else if (signType == "SS") {
                sec = date.getSeconds();
            }
            if (sec > 9 || !needZero) {
                secStr = sec.toString();
            } else {
                secStr = "0" + sec;
            }
            formatStr = formatStr.replace(signType, secStr);
        }
        return formatStr;
    }

    /**
     * 获取服务器时间字符串
     * @returns 返回格式化后的服务器时间字符串，格式为"YY-MT-DD HH:MM:SS"
     */
    public static getServerTimeStr(): string {
        return TimeUtil.formatTimeStamp(Laya.timer.currTimer);
    }

    /**
     * 获取时间数组
     * @returns 返回由服务器时间字符串分割后的数组
     */
    public static getTimeArr(): any[] {
        let str: string = TimeUtil.getServerTimeStr();
        let arr: any[] = str.split("/");
        return arr;
    }

    /**
     * 获取当前日期
     * @returns 返回当前日期的天数
     */
    public static get getDay(): number {
        let str: string = TimeUtil.getServerTimeStr();
        let arr: any[] = str.split("/");
        let day: number = parseInt(arr[2]);
        return day;
    }

    /**
     * 将时间数组格式化为时间字符串
     * @param time1 时间数组，每个元素代表时、分、秒等时间单位
     * @returns 返回格式化后的时间字符串，格式为"HH:MM:SS"，对于小于10的数字会补0
     */
    public static parseSheetTime(time1: any[]): string {
        let timeStr: string = "";
        if (time1) {
            let len: number = time1.length;
            for (let i: number = 0; i < len; i++) {
                let temp: string = "";
                if (time1[i] < 10) {
                    temp = "0" + time1[i];
                } else {
                    temp = time1[i];
                }
                if (i !== len - 1) {
                    temp = temp + ":";
                }
                timeStr += temp;
            }
        }
        return timeStr;
    }

    /**
     * 将日期字符串和小时转换为时间戳
     * @param dateString 日期字符串，格式为"YYYY-MM-DD"
     * @param hour 小时字符串
     * @returns 返回对应的时间戳（毫秒）
     */
    public static dateStringToTimestamp(dateString: string, hour: string): number {
        const [year, month, day] = dateString.split("-").map(Number);
        const hours = Number(hour);
        const timestamp = new Date(year, month - 1, day, hours).getTime();
        return Number(timestamp);
    }

    /**
     * 通过年、月、日、小时、分钟获得时间戳
     * @param year
     * @param month
     * @param day
     * @param hour
     * @param minute
     * @returns
     */
    public static getTimestamp(year: number, month: number, day: number, hour: number, minute: number): number {
        // 注意：月份是从0开始的，所以要减去1
        const date = new Date(year, month - 1, day, hour, minute);
        return date.getTime(); // 返回时间戳（毫秒）
    }

    /**
     * 获取当天的时间戳，保留小时但将分钟、秒和毫秒置为0
     * @returns 返回当天的时间戳（毫秒），精确到小时
     */
    public static getCurrentDayTimestamp(): number {
        const now = new Date();
        const hours = now.getHours();
        now.setHours(hours, 0, 0, 0); // 设置时分秒为0
        const timestamp = now.getTime();
        return timestamp;
    }

    /**
     * 将时间戳转换为年月日格式的字符串，对单位数字进行补零处理
     * @param timestamp 时间戳（毫秒）
     * @param separator 日期分隔符，默认为"-"
     * @returns 返回格式化后的日期字符串，格式为"YYYY-MM-DD"，如"2023-01-09"
     */
    public static getYearMonthDat(timestamp: number, separator: string = "-") {
        const date = new Date(timestamp); // 将时间戳转换为日期对象
        const year = date.getFullYear();
        const month = date.getMonth() + 1 < 10 ? "0" + (date.getMonth() + 1) : "" + (date.getMonth() + 1);
        const day = date.getDate() < 10 ? "0" + date.getDate() : "" + date.getDate();
        return `${year}${separator}${month}${separator}${day}`;
    }

    /**
     * 根据时间戳获取日期和时间
     * @param timestamp
     * @returns
     */
    public static formatDayAndTime(timestamp: number, symbol: string = "-"): { date: string; time: string } {
        const dateObj = new Date(timestamp);
        // 获取年月日
        const year = dateObj.getFullYear();
        const month = String(dateObj.getMonth() + 1).padStart(2, "0");
        const day = String(dateObj.getDate()).padStart(2, "0");

        // 获取时分
        const hours = String(dateObj.getHours()).padStart(2, "0");
        const minutes = String(dateObj.getMinutes()).padStart(2, "0");
        return {
            date: `${year}${symbol}${month}${symbol}${day}`,
            time: `${hours}:${minutes}`
        };
    }

    public static formatTimeExpires(diff: number): string {
        if (diff < 60 * 1000) {
            return GameLanguageMgr.getLanguage(1214, diff); //i0秒后过期
        } else if (diff < 60 * 60 * 1000) {
            // {0} 分钟后过期
            return GameLanguageMgr.getLanguage(1215, Math.floor(diff / 60000));
        } else if (diff < 24 * 60 * 60 * 1000) {
            // {0} 小时后过期
            return GameLanguageMgr.getLanguage(1216, Math.floor(diff / 3600000));
        } else {
            // {0} 天后过期
            return GameLanguageMgr.getLanguage(1217, Math.floor(diff / (24 * 60 * 60 * 1000)));
        }
    }

    /**
     * 距离目标时间戳剩余时间
     * @param targetTimestamp 目标时间戳
     * @param maxUnit 最大的格式,比如只需要从天开始计算,就传入day,默认从月开始
     * @returns
     */
    public static getTimeDifference(targetTimestamp: number, maxUnit: string = EnumTime.MONTH) {
        const currentTime = new Date();
        const targetTime = new Date(targetTimestamp * 1000); // 将Unix时间戳转换为毫秒

        // 计算时间差，以毫秒为单位
        const timeDifference = targetTime.getTime() - currentTime.getTime();

        if (timeDifference < 0) {
            return {
                months: 0,
                days: 0,
                hours: 0,
                minutes: 0,
                seconds: 0,
                ms: 0
            };
        }

        // 将时间差转换为不同的时间单位
        let ms = timeDifference; // 剩余的总毫秒数
        let seconds = Math.floor(timeDifference / 1000);
        let minutes = Math.floor(seconds / 60);
        let hours = Math.floor(minutes / 60);
        let days = Math.floor(hours / 24);
        let months = Math.floor(days / 30); // 粗略估算月数

        // 计算剩余的天、小时、分钟和秒
        // 根据 maxUnit 参数来确定从哪个单位开始计算
        if (maxUnit === "months") {
            days %= 30;
            hours %= 24;
            minutes %= 60;
            seconds %= 60;
            ms %= 1000;
        } else if (maxUnit === "days") {
            hours %= 24;
            minutes %= 60;
            seconds %= 60;
            ms %= 1000;
            months = 0; // 不需要计算月数
        } else if (maxUnit === "hours") {
            minutes %= 60;
            seconds %= 60;
            ms %= 1000;
            months = 0;
            days = 0; // 不需要计算天数
        } else if (maxUnit === "minutes") {
            seconds %= 60;
            ms %= 1000;
            months = 0;
            days = 0;
            hours = 0; // 不需要计算小时
        } else if (maxUnit === "seconds") {
            ms %= 1000;
            months = 0;
            days = 0;
            hours = 0;
            minutes = 0; // 不需要计算分钟
        } else if (maxUnit === "ms") {
            months = 0;
            days = 0;
            hours = 0;
            minutes = 0;
            seconds = 0; // 只需要计算毫秒
        }

        return {
            months: maxUnit === "months" ? months : 0,
            days: maxUnit === "months" || maxUnit === "days" ? days : 0,
            hours: maxUnit === "months" || maxUnit === "days" || maxUnit === "hours" ? hours : 0,
            minutes: maxUnit === "months" || maxUnit === "days" || maxUnit === "hours" || maxUnit === "minutes" ? minutes : 0,
            seconds: maxUnit !== "ms" ? seconds : 0,
            ms: ms
        };
    }

    /**
     * 检查时间戳是否在23.5小时内有效
     * @param timestamp 时间戳（秒）
     * @returns 如果时间戳在当前时间的23.5小时内，则返回true；否则返回false
     */
    public static checkTimeValid(timestamp: number): boolean {
        // return false;
        const currentTime = Math.floor(Date.now()); // 当前时间戳（毫秒）
        const oneDay = 23.5 * 60 * 60 * 1000; // 23.5小时的毫秒数
        // 如果时间戳超过当前时间的23.5小时，返回false
        if (currentTime - timestamp > oneDay) {
            return false;
        }
        return true;
    }

    /**
     * 检查时间戳是否在有效期内
     * @param timestamp 时间戳（毫秒）
     * @returns 如果时间戳在有效期内，则返回true；否则返回false
     */
    public static checkTimeValid2(timestamp: number): boolean {
        const currentTime = new Date().getTime();
        return currentTime < timestamp;
    }

    /**
     * 将时间戳转换为相对时间描述
     * @param timestamp 时间戳（毫秒）
     * @returns 返回相对时间描述，如"xx minutes ago"或"xx hours ago"
     */
    public static formatTimeAgoFromTimestamp(timestamp: number): string {
        const now = new Date().getTime();
        const diffMs = now - timestamp;
        const diffMinutes = Math.floor(diffMs / (60 * 1000));

        let timeString = "";
        if (diffMinutes < 60) {
            timeString = GameLanguageMgr.getLanguage(17, diffMinutes); // xx 分钟 ago
        } else if (diffMinutes < 24 * 60) {
            const diffHours = Math.floor(diffMinutes / 60);
            timeString = GameLanguageMgr.getLanguage(15, diffHours); // xx 小时 ago
        } else {
            const diffDays = Math.floor(diffMinutes / (24 * 60));
            timeString = GameLanguageMgr.getLanguage(16, diffDays); // xx 天 ago
        }
        return GameLanguageMgr.getLanguage(18, timeString);
    }

    /**
     * 将时间差转换为过期时间提示文本
     * @param diff 时间差（毫秒）
     * @returns 根据时间差返回不同的过期提示：
     */
    public static formatTimeAgo(diff: number): string {
        if (diff < 60 * 1000) {
            return GameLanguageMgr.getLanguage(40); //"在线");
        } else if (diff < 60 * 60 * 1000) {
            var timeString = GameLanguageMgr.getLanguage(17, Math.floor(diff / 60000));
            return GameLanguageMgr.getLanguage(18, timeString); //分钟前
        } else if (diff < 24 * 60 * 60 * 1000) {
            var timeString = GameLanguageMgr.getLanguage(15, Math.floor(diff / 3600000));
            return GameLanguageMgr.getLanguage(18, timeString); //小时前
        } else {
            var timeString = GameLanguageMgr.getLanguage(16, Math.floor(diff / (24 * 60 * 60 * 1000)));
            return GameLanguageMgr.getLanguage(18, timeString); //天前
        }
    }

    /**
     * 将时间戳格式化为"DD/MM/YYYY"格式的日期字符串
     * @param timestamp 时间戳（毫秒）
     * @param separator 日期分隔符，默认为"/"
     * @returns 返回格式化后的日期字符串，格式为"DD/MM/YYYY"，如"18/05/2025"
     */
    public static formatDateDDMMYYYY(timestamp: number, separator: string = "/"): string {
        const date = new Date(timestamp);
        const day = String(date.getDate()).padStart(2, "0");
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const year = date.getFullYear();

        return `${day}${separator}${month}${separator}${year}`;
    }

    public static getRestTime(endTimeStamp: number): string {
        // 获取当前时间戳（秒）
        const nowTime = Math.floor(Date.now() / 1000);

        // 计算剩余时间（秒）
        let restTime = endTimeStamp - nowTime;

        return this.getReduceTime(restTime);
    }
    public static getReduceTime(restTime: number): string {
        // 如果剩余时间小于0，则返回"00:00:00"
        if (restTime <= 0) {
            return "00:00:00";
        }

        // 计算小时、分钟和秒
        const hours = Math.floor(restTime / 3600);
        restTime %= 3600;
        const minutes = Math.floor(restTime / 60);
        const seconds = restTime % 60;

        // 格式化为"HH:MM:SS"
        const formattedHours = hours < 10 ? `0${hours}` : `${hours}`;
        const formattedMinutes = minutes < 10 ? `0${minutes}` : `${minutes}`;
        const formattedSeconds = seconds < 10 ? `0${seconds}` : `${seconds}`;

        return `${formattedHours}:${formattedMinutes}:${formattedSeconds}`;
    }

    /**
     * 获取从今天往前数七天的日期（包括今天）
     * @param separator 日期分隔符，默认为"-"
     * @returns 返回包含最近七天日期的数组，格式为"YYYY-MM-DD"，如["2023-01-01", "2023-01-02", ...]
     */
    public static getLastSevenDays(separator: string = "-"): string[] {
        const result: string[] = [];
        const oneDay = 24 * 60 * 60 * 1000; // 一天的毫秒数

        // 获取今天的日期，并设置时间为00:00:00
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        // 生成最近七天的日期（包括今天）
        for (let i = 0; i < 7; i++) {
            const date = new Date(today.getTime() - i * oneDay);
            const year = date.getFullYear();
            const month = date.getMonth() + 1 < 10 ? `0${date.getMonth() + 1}` : `${date.getMonth() + 1}`;
            const day = date.getDate() < 10 ? `0${date.getDate()}` : `${date.getDate()}`;
            result.push(`${year}$${month}$${day}`);
        }

        return result;
    }

    /**
     * 根据特定格式的日期字符串转换为中文或英文显示格式
     * @param dateStr 日期字符串，格式为"year$month$day"，如"2023$05$12"
     * @param isChinese 是否使用中文格式，true为中文格式（如"5月12日"），false为英文格式（如"May 12"）
     * @returns 包含原始日期和格式化日期的对象
     */
    public static formatDateDisplay(dateStr: string, isChinese: boolean = true): { original: string; formatted: string } {
        // 分割日期字符串获取年月日
        const parts = dateStr.split("$");
        if (parts.length !== 3) {
            return { original: dateStr, formatted: dateStr }; // 格式不正确时返回原字符串
        }

        const year = parseInt(parts[0]);
        const month = parseInt(parts[1]);
        const day = parseInt(parts[2]);

        // 创建日期对象
        const date = new Date(year, month - 1, day);
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);

        let formattedDate: string;

        // 检查是否是今天或昨天
        if (date.getTime() === today.getTime()) {
            formattedDate = "Today";
        } else if (date.getTime() === yesterday.getTime()) {
            formattedDate = "Yesterday";
        } else {
            if (isChinese) {
                // 中文格式：月月日日，如"5月12日"
                formattedDate = `${month}月${day}日`;
            } else {
                // 英文格式：月份简写 日，如"May 12"
                const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                formattedDate = `${monthNames[month - 1]} ${day}`;
            }
        }

        return {
            original: dateStr,
            formatted: formattedDate
        };
    }
}
