const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { MatchSkillIconItemBase } from "./MatchSkillIconItem.generated";

@regClass('iwuFUCOEQRyOjxpy6IkQ2Q==')
export class MatchSkillIconItem extends MatchSkillIconItemBase {
    public skillItem: any;
    public isBig: boolean = false;

    public constructor() {
        super();
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.skillItem = value;
        if (!this.skillItem) {
            return;
        }
        this.txt_num.text = "";
        this.img_icon.skin = GameResourceManager.getMatchSkillIcon(this.skillItem.icon); //"https://cdn.bunnyswap.cc/images/items/"+itemsStItem.icon;
    }
}
