import { MailVo } from "../../data/vo/pack/MailVo";
import { TimeUtil } from "../../utils/TimeUtil";
import { MillListItemBase } from "./MillListItem.generated";
const { regClass } = Laya;

@regClass('3h2PsGTIQV6ilXcpYeJ0cQ==')
export class MillListItem extends MillListItemBase {
    public mailVo: MailVo;

    public constructor() {
        super();
    }

    onEnable(): void {}
    //橙色  fdd378

    public set dataSource(value: any) {
        super.dataSource = value;
        this.mailVo = value as any;
        if (!this.mailVo) {
            return;
        }
        this.tf_title.text = this.mailVo.title;
        this.tf_from.text = this.mailVo.sendName;
        this.img_red.visible = !this.mailVo.read;
        this.img_isRead.visible = this.mailVo.read;
        this.tf_time.text = TimeUtil.formatTimeAgoFromTimestamp(this.mailVo.sendTime);
    }
}
